#[test]
fn rejects_moving_list_owner_while_zero_copy_view_is_live() {
    let live_slice = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let tail: i64[] = source[1:]
    let destination: i64[] = source
    print(tail[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_slice)
        .expect_err("moving a list owner while a slice borrow is live must fail");
    let borrow_error = errors
        .iter()
        .find(|error| {
            error
                .message
                .contains("while borrowed view 'tail' is still live")
        })
        .expect("the live borrowed view should be identified");
    assert!(
        borrow_error
            .labels
            .iter()
            .any(|label| label.message.contains("'tail' borrows from 'source'"))
    );

    let dead_slice = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let tail: i64[] = source[1:]
    print(tail[0])
    let destination: i64[] = source
    print(destination[0])
    return 0
}
"#;
    check_source(dead_slice).expect("a dead slice borrow must not prevent a later owner move");
    compile_to_c(dead_slice).expect("a move after the slice's last use should lower natively");
    let database = fluxc::semantic::SemanticDatabase::analyze(dead_slice, SourceId::new(1208))
        .expect("borrow provenance should remain available through semantic CFG analysis");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    assert!(
        graph.borrowed_definition_span("tail", "source").is_some(),
        "normalized ownership IR should expose the zero-copy borrow source"
    );

    let chained_view = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30, 40]
    let tail: i64[] = source[1:]
    let lastTwo: i64[] = tail | take 2
    let destination: i64[] = source
    print(lastTwo[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(chained_view)
        .expect_err("transitive zero-copy view borrows must keep the owner live");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'lastTwo' is still live")
    }));

    let live_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30, 40]
    let [_, ...middle, _] = source
    let destination: i64[] = source
    print(middle[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_rest)
        .expect_err("a live list-rest view must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'middle' is still live")
    }));

    let live_nested_element = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let [first, ..._] = source
    let destination: i64[][] = source
    print(first[0])
    print(destination[0][0])
    return 0
}
"#;
    let errors = check_source_all(live_nested_element)
        .expect_err("a destructured nested-list element is a borrowed view");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'first' is still live")
    }));

    let live_match_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    match source:
        []:
            print 0
        [_, ...middle]:
            let destination: i64[] = source
            print(middle[0])
            print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_match_rest)
        .expect_err("a live list-match rest binding must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'middle' is still live")
    }));

    for property in ["first", "last", "single"] {
        let live_property = format!(
            "fn main() -> i64 {{\n    let source: i64[][] = [[10, 20], [30, 40]]\n    let view: i64[] = source.{property}\n    let destination: i64[][] = source\n    print(view[0])\n    print(destination[0][0])\n    return 0\n}}\n"
        );
        let errors = check_source_all(&live_property)
            .expect_err("a live nested-list property view must keep its owner borrowed");
        assert!(errors.iter().any(|error| {
            error
                .message
                .contains("while borrowed view 'view' is still live")
        }));
    }

    let dead_property = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let view: i64[] = source.first
    print(view[0])
    let destination: i64[][] = source
    print(destination[0][0])
    return 0
}
"#;
    check_source(dead_property)
        .expect("a dead nested-list property borrow must not prevent a later owner move");
    compile_to_c(dead_property)
        .expect("a move after a nested-list property view's last use should lower natively");

    let chained_view = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let view: i64[] = source[0][1:]
    let destination: i64[][] = source
    print(view[0])
    print(destination[0][0])
    return 0
}
"#;
    let errors = check_source_all(chained_view)
        .expect_err("a chained zero-copy view must retain the original owner borrow");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'view' is still live")
    }));

    let dead_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let [_, ...middle] = source
    print(middle[0])
    let destination: i64[] = source
    print(destination[0])
    return 0
}
"#;
    check_source(dead_rest).expect("a dead list-rest borrow must not prevent a later owner move");
}

