#[test]
fn list_match_statements_and_expressions_are_exhaustive_typed_and_native() {
    let source = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40]
    match values[::-1]:
        []:
            print 0
        [single]:
            print single
        [first, ...middle, last]:
            print first
            print middle.length
            print middle.first
            print middle.last
            print last
    let count: i64 = match values:
        []: 0
        [_]: 1
        [_, ...body, _]: body.length + 2
    print count
    return 0
}
"#;

    check_source(source).expect("list matches should typecheck");
    let generated = compile_to_c(source).expect("list matches should lower natively");
    assert!(generated.contains("flux__list_match_"));
    assert!(generated.contains(".len == 0"));
    assert!(generated.contains(".len == 1"));
    assert!(generated.contains(".len >= 2"));
    assert!(generated.contains(".len - 1, sizeof(int64_t)"));
    assert!(generated.contains("flux_list_stride(flux__list_match_"));

    let formatted = fluxc::formatter::format_source(source).expect("list match should format");
    assert!(formatted.contains("[first, ...middle, last]:"));
    assert!(formatted.contains("[_, ...body, _]: body.length + 2"));
    let formatted_again =
        fluxc::formatter::format_source(&formatted).expect("formatted list match should reparse");
    assert_eq!(formatted_again, formatted);

    let database = fluxc::semantic::SemanticDatabase::analyze(&formatted, SourceId::new(743))
        .expect("list match should analyze semantically");
    let middle = database
        .symbols_named("middle")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::PatternBinding)
        .expect("list rest match binding should be indexed");
    assert_eq!(
        middle.ty,
        Some(fluxc::ast::Type::List(Box::new(fluxc::ast::Type::I64)))
    );
    let first = database
        .symbols_named("first")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::PatternBinding)
        .expect("list element match binding should be indexed");
    assert_eq!(first.ty, Some(fluxc::ast::Type::I64));

    let graph = database
        .control_flow_graph("main")
        .expect("list match fixture should expose typed IR");
    let list_match = graph
        .values()
        .iter()
        .find_map(|value| match &value.kind {
            ControlFlowValueKind::ListMatch { arms, .. } if arms.len() == 3 => Some(arms),
            _ => None,
        })
        .expect("value-producing list match should be normalized");
    let body_arm = graph
        .value(list_match[2])
        .expect("rest-pattern arm should retain its value expression");
    let ControlFlowValueKind::Binary { left, .. } = &body_arm.kind else {
        panic!("rest-pattern arm should retain its body-length addition");
    };
    let ControlFlowValueKind::Field { base, .. } = &graph
        .value(*left)
        .expect("rest-pattern body length should retain its field access")
        .kind
    else {
        panic!("rest-pattern expression should read the rest-list length");
    };
    let ControlFlowValueKind::NameRead { name, definitions } = &graph
        .value(*base)
        .expect("rest-pattern field should retain its binding read")
        .kind
    else {
        panic!("rest-pattern field base should be a name read");
    };
    assert_eq!(name, "body");
    assert_eq!(definitions.len(), 1);
    assert!(matches!(
        definitions[0],
        ControlFlowDefinitionId::Scoped { .. }
    ));
    assert_eq!(graph.definition_name(definitions[0]), Some("body"));
}

#[test]
