#[test]
fn semantic_database_exposes_structural_control_flow_graphs_with_source_spans() {
    let source_id = SourceId::new(1305);
    let source = r#"
fn route(flag: bool) -> i64 {
    let value: i64 = 1
    while flag:
        if value == 1:
            break
        continue
    return value
}

fn main() -> i64 {
    return route(false)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, source_id)
        .expect("valid control flow should analyze");
    let graph = database
        .control_flow_graph("route")
        .expect("semantic database should expose a graph for every function");

    assert_eq!(graph.function(), "route");
    assert_eq!(graph.parameters().len(), 1);
    assert_eq!(graph.parameters()[0].name, "flag");
    assert_eq!(graph.parameters()[0].ty, fluxc::ast::Type::Bool);
    assert_eq!(graph.returns(), &[fluxc::ast::Type::I64]);
    assert_eq!(database.control_flow_graphs().len(), 2);
    assert!(
        graph
            .nodes()
            .iter()
            .all(|node| node.span.source_id == source_id)
    );
    assert!(graph.nodes().iter().any(|node| matches!(
        &node.kind,
        ControlFlowNodeKind::Binding { name, ty, mutable: false }
            if name == "value" && *ty == fluxc::ast::Type::I64
    )));
    for expected in [
        ControlFlowNodeKind::Loop,
        ControlFlowNodeKind::Conditional,
        ControlFlowNodeKind::Break,
        ControlFlowNodeKind::Continue,
        ControlFlowNodeKind::Return,
    ] {
        assert!(
            graph
                .nodes()
                .iter()
                .any(|node| std::mem::discriminant(&node.kind) == std::mem::discriminant(&expected)),
            "missing control-flow node {expected:?}"
        );
    }
    for expected in [
        ControlFlowEdgeKind::True,
        ControlFlowEdgeKind::False,
        ControlFlowEdgeKind::Break,
        ControlFlowEdgeKind::Continue,
        ControlFlowEdgeKind::Return,
    ] {
        assert!(
            graph.edges().iter().any(|edge| edge.kind == expected),
            "missing control-flow edge {expected:?}"
        );
    }
    let loop_node = graph
        .nodes()
        .iter()
        .find(|node| matches!(node.kind, ControlFlowNodeKind::Loop))
        .expect("loop node should exist");
    assert!(
        graph
            .outgoing(loop_node.id)
            .any(|edge| edge.kind == ControlFlowEdgeKind::True)
    );
    assert!(
        graph
            .outgoing(loop_node.id)
            .any(|edge| edge.kind == ControlFlowEdgeKind::False)
    );
    let continue_edge = graph
        .edges()
        .iter()
        .find(|edge| edge.kind == ControlFlowEdgeKind::Continue)
        .expect("continue edge should exist");
    let condition = graph
        .node(continue_edge.to)
        .expect("continue should target condition re-evaluation");
    assert!(matches!(
        condition.kind,
        ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::Condition)
    ));
    assert!(
        graph
            .outgoing(condition.id)
            .any(|edge| edge.kind == ControlFlowEdgeKind::Next && edge.to == loop_node.id)
    );

    let propagation = r#"
fn load(path: str) -> (str, error) {
    if path == "":
        return "", error("missing")
    return path, nil
}

fn loadConfig(path: str) -> (str, error) {
    let data: str, err: error = load(path) else return
    print(data)
    return data, nil
}

fn main() -> i64 {
    return 0
}
"#;
    let propagation_database =
        fluxc::semantic::SemanticDatabase::analyze(propagation, SourceId::new(1306))
            .expect("explicit error propagation should analyze");
    let propagation_graph = propagation_database
        .control_flow_graph("loadConfig")
        .expect("error-propagating function should have a graph");
    let destructure = propagation_graph
        .nodes()
        .iter()
        .find(|node| {
            matches!(
                node.kind,
                ControlFlowNodeKind::Destructure {
                    propagates_error: true
                }
            )
        })
        .expect("else-return destructuring should be explicit in the graph");
    let destructure_evaluation = propagation_graph
        .incoming(destructure.id)
        .find_map(|edge| propagation_graph.node(edge.from))
        .expect("destructure source evaluation should precede propagation");
    assert_eq!(
        destructure_evaluation.value_types,
        vec![fluxc::ast::Type::Str, fluxc::ast::Type::Error]
    );
    assert_eq!(destructure_evaluation.values.len(), 2);
    for (index, value_id) in destructure_evaluation.values.iter().enumerate() {
        let value = propagation_graph
            .value(*value_id)
            .expect("typed CFG value should be indexed by its deterministic id");
        assert_eq!(value.producer, destructure_evaluation.id);
        assert_eq!(value.result_index, Some(index));
        assert_eq!(value.ty, destructure_evaluation.value_types[index]);
        assert_eq!(value.span, destructure_evaluation.span);
    }
    let outgoing = propagation_graph
        .outgoing(destructure.id)
        .map(|edge| edge.kind)
        .collect::<Vec<_>>();
    assert!(outgoing.contains(&ControlFlowEdgeKind::Success));
    assert!(outgoing.contains(&ControlFlowEdgeKind::Error));
    assert!(propagation_graph.outgoing(destructure.id).any(|edge| {
        edge.kind == ControlFlowEdgeKind::Error && edge.to == propagation_graph.exit()
    }));

    let ownership_source = r#"
fn consume() -> i64 {
    let source: i64[] = [1, 2]
    let destination: i64[] = source
    print(destination.first)
    return 0
}

fn main() -> i64 {
    return consume()
}
"#;
    let ownership_database =
        fluxc::semantic::SemanticDatabase::analyze(ownership_source, SourceId::new(1307))
            .expect("direct ownership transfer should analyze");
    let ownership_graph = ownership_database
        .control_flow_graph("consume")
        .expect("ownership function should have a graph");
    let destination = ownership_graph
        .nodes()
        .iter()
        .find(|node| {
            matches!(
                &node.kind,
                ControlFlowNodeKind::Binding { name, .. } if name == "destination"
            )
        })
        .expect("destination binding should be explicit in the graph");
    assert!(destination.ownership.reads.is_empty());
    assert_eq!(destination.ownership.moves.len(), 1);
    let ownership_move = &destination.ownership.moves[0];
    assert_eq!(ownership_move.source, "source");
    assert_eq!(ownership_move.destination, "destination");
    assert_eq!(ownership_move.span.source_id, SourceId::new(1307));

    let source_evaluation = ownership_graph
        .incoming(destination.id)
        .find_map(|edge| ownership_graph.node(edge.from))
        .expect("binding initializer evaluation should precede the move");
    assert!(matches!(
        source_evaluation.kind,
        ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::BindingInitializer)
    ));
    assert_eq!(
        source_evaluation.value_types,
        vec![fluxc::ast::Type::List(Box::new(fluxc::ast::Type::I64))]
    );
    assert_eq!(source_evaluation.values.len(), 1);
    let source_value = ownership_graph
        .value(source_evaluation.values[0])
        .expect("initializer should produce one typed CFG value");
    assert_eq!(source_value.producer, source_evaluation.id);
    assert_eq!(source_value.result_index, Some(0));
    assert_eq!(source_value.ty, source_evaluation.value_types[0]);
    assert_eq!(source_evaluation.ownership.reads, vec!["source"]);
    assert_eq!(source_evaluation.ownership.borrows.len(), 1);
    assert_eq!(source_evaluation.ownership.borrows[0].source, "source");
    assert_eq!(
        source_evaluation.ownership.borrows[0].span,
        source_value.span
    );
    assert!(source_evaluation.ownership.moves.is_empty());

    let destination_read = ownership_graph
        .nodes()
        .iter()
        .find(|node| {
            node.ownership
                .reads
                .iter()
                .any(|read| read == "destination")
        })
        .expect("later expression evaluation should retain its binding reads");
    assert!(
        destination_read
            .ownership
            .borrows
            .iter()
            .any(|borrow| borrow.source == "destination")
    );
    let moved_before_read = ownership_graph
        .move_state_before(destination_read.id)
        .expect("every graph node should have a move-state slot");
    assert!(moved_before_read.reachable());
    assert!(moved_before_read.is_moved("source"));
    assert_eq!(
        moved_before_read.origin("source"),
        Some(ownership_move.span)
    );
}

#[test]
fn semantic_cfg_normalizes_nested_expression_values() {
    let source = r#"
fn scale(input: i64) -> i64 {
    let result: i64 = (input + 2) * 3
    return result
}

fn main() -> i64 {
    return scale(4)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1310))
        .expect("nested primitive expression should analyze");
    let graph = database
        .control_flow_graph("scale")
        .expect("scale should have a control-flow graph");
    let evaluation = graph
        .nodes()
        .iter()
        .find(|node| {
            matches!(
                node.kind,
                ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::BindingInitializer)
            )
        })
        .expect("binding initializer should be explicit");
    assert_eq!(evaluation.values.len(), 1);
    let root = graph
        .value(evaluation.values[0])
        .expect("initializer should have a typed result value");
    assert_eq!(root.result_index, Some(0));
    let ControlFlowValueKind::Binary {
        op: fluxc::ast::BinOp::Mul,
        left,
        right,
    } = root.kind
    else {
        panic!("initializer root should be the multiplication value");
    };
    let multiply_right = graph.value(right).expect("multiply RHS should be typed");
    assert_eq!(multiply_right.result_index, None);
    assert!(matches!(multiply_right.kind, ControlFlowValueKind::Literal));
    assert!(matches!(
        multiply_right.constant,
        Some(fluxc::typecheck::ConstantValue::I64(3))
    ));

    let addition = graph.value(left).expect("multiply LHS should be typed");
    let ControlFlowValueKind::Binary {
        op: fluxc::ast::BinOp::Add,
        left: add_left,
        right: add_right,
    } = addition.kind
    else {
        panic!("multiply LHS should retain the nested addition");
    };
    assert_eq!(addition.result_index, None);
    let input = graph
        .value(add_left)
        .expect("addition input should be typed");
    assert!(matches!(
        &input.kind,
        ControlFlowValueKind::NameRead { name, .. } if name == "input"
    ));
    assert_eq!(input.constant, None);
    assert_eq!(addition.constant, None);
    assert_eq!(root.constant, None);
    assert!(matches!(
        graph.value(add_right).map(|value| &value.kind),
        Some(ControlFlowValueKind::Literal)
    ));
    assert!(
        [root.id, left, right, add_left, add_right]
            .into_iter()
            .all(|id| graph
                .value(id)
                .is_some_and(|value| value.producer == evaluation.id))
    );
}

#[test]
fn semantic_cfg_tracks_control_dependent_value_uses_and_prunes_short_circuit_rhs() {
    let source = r#"
fn dead() -> bool {
    return true
}

fn main() -> i64 {
    if false && dead():
        return 1
    return 0
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1316))
        .expect("short-circuit expression should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let root = graph
        .values()
        .iter()
        .find(|value| {
            matches!(
                value.kind,
                ControlFlowValueKind::Binary {
                    op: fluxc::ast::BinOp::And,
                    ..
                }
            ) && value.result_index == Some(0)
        })
        .expect("condition should expose a typed short-circuit root");
    let ControlFlowValueKind::Binary { left, right, .. } = root.kind else {
        unreachable!();
    };
    assert!(graph.is_value_reachable(root.id));
    assert!(graph.is_value_reachable(left));
    assert!(!graph.is_value_reachable(right));
    let short_circuit_use = graph
        .uses_from(root.id)
        .find(|usage| {
            usage.value == right && usage.kind == ControlFlowValueUseKind::ShortCircuitRight
        })
        .expect("short-circuit RHS should be attached to an explicit IR region");
    let region = graph
        .value_region(
            short_circuit_use
                .region
                .expect("short-circuit use should name its region"),
        )
        .expect("short-circuit region should exist");
    assert_eq!(region.owner, root.id);
    assert_eq!(region.root, right);
    assert_eq!(
        region.span,
        graph.value(right).expect("RHS value should exist").span
    );
    assert!(matches!(
        region.kind,
        ControlFlowValueRegionKind::ShortCircuitRight {
            condition,
            execute_when: true,
        } if condition == left
    ));
    assert!(graph.uses_of(right).any(|usage| usage.user == root.id));

    let generated = compile_to_c(source).expect("short-circuit program should lower natively");
    assert!(!generated.contains("flux__fn_dead"));
}

#[test]
fn semantic_cfg_prunes_statically_unselected_list_control_values() {
    let source = r#"
fn live() -> i64 {
    return 1
}

fn dead() -> i64 {
    return 2
}

fn main() -> i64 {
    let values: i64[] = [if true: live() else: dead()]
    return values.first
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1317))
        .expect("static list control should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let list_if = graph
        .values()
        .iter()
        .find(|value| matches!(value.kind, ControlFlowValueKind::ListIf { .. }))
        .expect("list control item should have typed IR");
    let ControlFlowValueKind::ListIf {
        condition,
        value,
        else_value: Some(else_value),
    } = list_if.kind
    else {
        panic!("list control item should retain both source branches");
    };
    assert!(graph.is_value_reachable(list_if.id));
    assert!(graph.is_value_reachable(condition));
    assert!(graph.is_value_reachable(value));
    assert!(!graph.is_value_reachable(else_value));
    let then_use = graph
        .uses_from(list_if.id)
        .find(|usage| usage.value == value && usage.kind == ControlFlowValueUseKind::BranchThen)
        .expect("selected list branch should be explicit in IR");
    let else_use = graph
        .uses_from(list_if.id)
        .find(|usage| {
            usage.value == else_value && usage.kind == ControlFlowValueUseKind::BranchElse
        })
        .expect("unselected list branch should remain represented in IR");
    assert!(matches!(
        graph
            .value_region(then_use.region.expect("then branch should name its region"))
            .map(|region| region.kind),
        Some(ControlFlowValueRegionKind::Branch {
            condition: branch_condition,
            selected_when: true,
        }) if branch_condition == condition
    ));
    assert!(matches!(
        graph
            .value_region(else_use.region.expect("else branch should name its region"))
            .map(|region| region.kind),
        Some(ControlFlowValueRegionKind::Branch {
            condition: branch_condition,
            selected_when: false,
        }) if branch_condition == condition
    ));
    assert_eq!(graph.regions_owned_by(list_if.id).count(), 2);

    let generated = compile_to_c(source).expect("static list control should lower natively");
    assert!(generated.contains("flux__fn_live"));
    assert!(!generated.contains("flux__fn_dead"));
}

#[test]
fn propagated_constants_do_not_prune_nested_values_before_backend_ir_lowering() {
    let source = r#"
fn live() -> i64 {
    return 1
}

fn dead() -> i64 {
    return 2
}

fn main() -> i64 {
    let enabled: bool = true
    let values: i64[] = [if enabled: live() else: dead()]
    return values.first
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1318))
        .expect("propagated list-control condition should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let list_if = graph
        .values()
        .iter()
        .find(|value| matches!(value.kind, ControlFlowValueKind::ListIf { .. }))
        .expect("list control item should retain typed IR");
    let ControlFlowValueKind::ListIf {
        condition,
        else_value: Some(else_value),
        ..
    } = list_if.kind
    else {
        panic!("list control item should retain its else branch");
    };
    let condition = graph
        .value(condition)
        .expect("list condition should retain its typed value");
    assert_eq!(condition.source_constant, None);
    assert_eq!(
        condition.constant,
        Some(fluxc::typecheck::ConstantValue::Bool(true))
    );
    assert!(graph.is_value_reachable(else_value));

    let generated =
        compile_to_c(source).expect("backend should keep emitted nested references valid");
    assert!(generated.contains("flux__fn_live"));
    assert!(generated.contains("flux__fn_dead"));
}

#[test]
fn semantic_cfg_resolves_name_reads_to_reaching_definitions() {
    let source = r#"
fn choose(input: i64, flag: bool) -> i64 {
    var current: i64 = input
    if flag:
        current = 10
    else:
        current = 20
    return current
}

fn main() -> i64 {
    return choose(1, true)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1313))
        .expect("definition-use fixture should analyze");
    let graph = database
        .control_flow_graph("choose")
        .expect("choose should have a control-flow graph");

    let input_read = graph
        .values()
        .iter()
        .find_map(|value| match &value.kind {
            ControlFlowValueKind::NameRead { name, definitions } if name == "input" => {
                Some(definitions)
            }
            _ => None,
        })
        .expect("initializer should read the input parameter");
    assert_eq!(input_read, &[ControlFlowDefinitionId::Parameter(0)]);

    let flag_read = graph
        .values()
        .iter()
        .find_map(|value| match &value.kind {
            ControlFlowValueKind::NameRead { name, definitions } if name == "flag" => {
                Some(definitions)
            }
            _ => None,
        })
        .expect("condition should read the flag parameter");
    assert_eq!(flag_read, &[ControlFlowDefinitionId::Parameter(1)]);

    let assignment_definitions = graph
        .nodes()
        .iter()
        .filter(|node| {
            matches!(
                &node.kind,
                ControlFlowNodeKind::Assignment { name } if name == "current"
            )
        })
        .map(|node| ControlFlowDefinitionId::Node {
            node: node.id,
            index: 0,
        })
        .collect::<std::collections::BTreeSet<_>>();
    assert_eq!(assignment_definitions.len(), 2);

    let return_read = graph
        .values()
        .iter()
        .find_map(|value| match &value.kind {
            ControlFlowValueKind::NameRead { name, definitions }
                if name == "current"
                    && matches!(
                        graph.node(value.producer).map(|node| &node.kind),
                        Some(ControlFlowNodeKind::Evaluation(
                            ControlFlowEvaluationKind::ReturnValue(0)
                        ))
                    ) =>
            {
                Some(
                    definitions
                        .iter()
                        .copied()
                        .collect::<std::collections::BTreeSet<_>>(),
                )
            }
            _ => None,
        })
        .expect("return should read the merged current value");
    assert_eq!(return_read, assignment_definitions);
    assert!(return_read.iter().all(|definition| {
        graph.definition_name(*definition) == Some("current")
            && graph.definition_span(*definition).is_some()
            && graph
                .definition_value(*definition)
                .and_then(|value| graph.value(value))
                .is_some_and(|value| {
                    matches!(
                        value.constant,
                        Some(fluxc::typecheck::ConstantValue::I64(10 | 20))
                    )
                })
    }));
}

#[test]
fn semantic_cfg_propagates_local_constants_into_control_flow() {
    let source = r#"
fn live() -> i64 {
    return 1
}

fn dead() -> i64 {
    return 2
}

fn main() -> i64 {
    let base: i64 = 20
    let half: i64 = base / 2
    let enabled: bool = half == 10
    if enabled:
        print(live())
    else:
        print(dead())
    return 0
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1315))
        .expect("local constant control flow should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let condition = graph
        .nodes()
        .iter()
        .find(|node| {
            matches!(
                node.kind,
                ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::Condition)
            )
        })
        .expect("if condition should be explicit");
    let condition_value = graph
        .value(condition.values[0])
        .expect("condition should retain its typed value");
    assert_eq!(
        condition_value.constant,
        Some(fluxc::typecheck::ConstantValue::Bool(true))
    );
    let branch = graph
        .outgoing(condition.id)
        .find(|edge| {
            graph
                .node(edge.to)
                .is_some_and(|node| matches!(node.kind, ControlFlowNodeKind::Conditional))
        })
        .expect("condition evaluation should feed an if branch");
    let outgoing = graph.outgoing(branch.to).collect::<Vec<_>>();
    assert!(
        outgoing
            .iter()
            .any(|edge| edge.kind == ControlFlowEdgeKind::True)
    );
    assert!(
        !outgoing
            .iter()
            .any(|edge| edge.kind == ControlFlowEdgeKind::False)
    );

    let generated = compile_to_c(source).expect("locally constant branch should lower");
    assert!(generated.contains("flux__fn_live"));
    assert!(!generated.contains("flux__fn_dead"));
}

#[test]
fn semantic_cfg_normalizes_match_and_comprehension_subgraphs() {
    let source = r#"
enum Choice {
    One(i64)
    None
}

fn main() -> i64 {
    let choice: Choice = Choice.One(2)
    let selected: i64 = match choice:
        Choice.One(value): value * 2
        Choice.None(): 0
    let values: i64[] = [1, 2, 3]
    let mapped: i64[] = [value * 3 for value in values if value > 1]
    return selected + mapped.length
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1312))
        .expect("control-dependent expressions should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");

    let match_value = graph
        .values()
        .iter()
        .find(|value| matches!(value.kind, ControlFlowValueKind::Match { .. }))
        .expect("match expression should have a typed IR root");
    let ControlFlowValueKind::Match {
        value,
        guards,
        arms,
    } = &match_value.kind
    else {
        unreachable!();
    };
    assert_eq!(guards, &[None, None]);
    assert_eq!(arms.len(), 2);
    assert!(matches!(
        graph.value(*value).map(|value| &value.kind),
        Some(ControlFlowValueKind::NameRead { name, .. }) if name == "choice"
    ));
    let match_arm = graph
        .value(arms[0])
        .expect("matched payload arm should retain its value expression");
    let ControlFlowValueKind::Binary {
        op: fluxc::ast::BinOp::Mul,
        left: match_binding_read,
        ..
    } = &match_arm.kind
    else {
        panic!("matched payload arm should retain its multiplication");
    };
    let match_binding_definitions = match &graph
        .value(*match_binding_read)
        .expect("match arm should retain its payload read")
        .kind
    {
        ControlFlowValueKind::NameRead { name, definitions } if name == "value" => definitions,
        _ => panic!("match payload should be a scoped name read"),
    };
    assert_eq!(match_binding_definitions.len(), 1);
    assert!(matches!(
        match_binding_definitions[0],
        ControlFlowDefinitionId::Scoped { .. }
    ));
    assert_eq!(
        graph.definition_name(match_binding_definitions[0]),
        Some("value")
    );
    assert!(matches!(
        graph.value(arms[1]).map(|value| &value.kind),
        Some(ControlFlowValueKind::Literal)
    ));

    assert!(graph.regions_owned_by(match_value.id).any(|region| {
        matches!(
            region.kind,
            ControlFlowValueRegionKind::MatchArm { arm: 0 | 1, .. }
        )
    }));

    let comprehension = graph
        .values()
        .iter()
        .find(|value| matches!(value.kind, ControlFlowValueKind::ListComprehension { .. }))
        .expect("list comprehension should have a typed IR root");
    let ControlFlowValueKind::ListComprehension {
        iterable,
        value,
        condition,
    } = &comprehension.kind
    else {
        unreachable!();
    };
    assert!(matches!(
        graph.value(*iterable).map(|value| &value.kind),
        Some(ControlFlowValueKind::NameRead { name, .. }) if name == "values"
    ));
    let comprehension_value = graph
        .value(*value)
        .expect("comprehension body should retain its value expression");
    let ControlFlowValueKind::Binary {
        op: fluxc::ast::BinOp::Mul,
        left: body_binding_read,
        ..
    } = &comprehension_value.kind
    else {
        panic!("comprehension body should retain its multiplication");
    };
    assert!(graph.regions_owned_by(comprehension.id).any(|region| {
        matches!(
            region.kind,
            ControlFlowValueRegionKind::LoopCondition { .. }
        )
    }));
    assert!(graph.regions_owned_by(comprehension.id).any(|region| {
        matches!(
            region.kind,
            ControlFlowValueRegionKind::LoopBody {
                condition: Some(_),
                ..
            }
        )
    }));
    let condition = condition
        .and_then(|condition| graph.value(condition))
        .expect("comprehension filter should retain its condition");
    let ControlFlowValueKind::Binary {
        op: fluxc::ast::BinOp::Gt,
        left: condition_binding_read,
        ..
    } = &condition.kind
    else {
        panic!("comprehension filter should retain its comparison");
    };
    let scoped_binding = |id| match &graph
        .value(id)
        .expect("comprehension binding read should be typed")
        .kind
    {
        ControlFlowValueKind::NameRead { name, definitions } if name == "value" => {
            assert_eq!(definitions.len(), 1);
            definitions[0]
        }
        _ => panic!("comprehension binding should be a scoped name read"),
    };
    let body_definition = scoped_binding(*body_binding_read);
    let condition_definition = scoped_binding(*condition_binding_read);
    assert_eq!(body_definition, condition_definition);
    assert!(matches!(
        body_definition,
        ControlFlowDefinitionId::Scoped { .. }
    ));
    assert_eq!(graph.definition_name(body_definition), Some("value"));
}

#[test]
fn semantic_cfg_records_concrete_interface_pack_targets() {
    let source = r#"
interface Tool {
    fn apply(value: i64) -> i64
}

struct Offset {
    amount: i64
}

fn applyOffset(receiver: Offset, value: i64) -> i64 {
    return receiver.amount + value
}

impl Tool for Offset {
    apply: applyOffset
}

fn main() -> i64 {
    let offset: Offset = Offset { amount: 2 }
    let direct: i64 = Tool.apply(offset, 1)
    let tool: Tool = Tool(offset)
    return direct + Tool.apply(tool, 40)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1311))
        .expect("interface packing should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let packed = graph
        .values()
        .iter()
        .find(|value| matches!(value.kind, ControlFlowValueKind::InterfacePack { .. }))
        .expect("interface conversion should retain its concrete target in typed IR");
    let ControlFlowValueKind::InterfacePack {
        interface,
        target,
        value,
    } = &packed.kind
    else {
        unreachable!();
    };
    assert_eq!(interface, "Tool");
    assert_eq!(target, "Offset");
    assert_eq!(packed.ty, fluxc::ast::Type::Named("Tool".to_string()));
    let input = graph
        .value(*value)
        .expect("interface pack should retain its concrete input dependency");
    assert_eq!(input.ty, fluxc::ast::Type::Named("Offset".to_string()));
    assert!(matches!(
        &input.kind,
        ControlFlowValueKind::NameRead { name, .. } if name == "offset"
    ));

    let dispatches = graph
        .values()
        .iter()
        .filter_map(|value| match &value.kind {
            ControlFlowValueKind::InterfaceDispatch {
                interface,
                capability,
                target,
                mapped_function,
                ..
            } => Some((interface, capability, target, mapped_function)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(dispatches.len(), 2);
    assert!(
        dispatches
            .iter()
            .any(|(interface, capability, target, mapped)| {
                *interface == "Tool"
                    && *capability == "apply"
                    && target.as_deref() == Some("Offset")
                    && mapped.as_deref() == Some("applyOffset")
            })
    );
    assert!(
        dispatches
            .iter()
            .any(|(interface, capability, target, mapped)| {
                *interface == "Tool"
                    && *capability == "apply"
                    && target.is_none()
                    && mapped.is_none()
            })
    );
}

#[test]
fn semantic_cfg_computes_local_liveness_for_dead_store_analysis() {
    let source = r#"
fn main() -> i64 {
    var value: i64 = 1
    value = 2
    value = 3
    return value
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1309))
        .expect("mutable local flow should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let mut assignments = graph
        .nodes()
        .iter()
        .filter(|node| {
            matches!(
                &node.kind,
                ControlFlowNodeKind::Assignment { name } if name == "value"
            )
        })
        .collect::<Vec<_>>();
    assignments.sort_by_key(|node| node.span.line);
    assert_eq!(assignments.len(), 2);
    assert!(
        !graph
            .live_after(assignments[0].id)
            .expect("assignment should have liveness facts")
            .contains("value"),
        "the first overwritten store should be dead"
    );
    assert!(
        graph
            .live_after(assignments[1].id)
            .expect("assignment should have liveness facts")
            .contains("value"),
        "the final store should stay live because return reads it"
    );
    assert_eq!(
        graph
            .live_after(assignments[0].id)
            .expect("liveness should be deterministic")
            .live(),
        &[] as &[String]
    );
}

#[test]
fn semantic_cfg_tracks_destructure_loop_and_match_definitions() {
    let source = r#"
struct Point {
    x: i64
    y: i64
}

enum Choice {
    Value(i64)
    Empty
}

fn pair() -> (i64, bool) {
    return 41, true
}

fn main() -> i64 {
    let (multiValue, multiOk) = pair()
    let [head, ...middle, tail] = [1, 2, 3]
    let Point { x, y } = Point { x: 4, y: 5 }
    if false:
        print(multiValue)
        print(multiOk)
        print(head)
        print(middle.length)
        print(tail)
        print(x)
        print(y)
    for index, item in [1, 2]:
        if false:
            print(index)
            print(item)
    match Choice.Value(9):
        Choice.Value(payload):
            if false:
                print(payload)
        Choice.Empty():
            print(0)
    return 0
}
"#;

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1311))
        .expect("definition-rich control flow should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");

    let definitions = graph
        .nodes()
        .iter()
        .flat_map(|node| {
            node.definitions
                .iter()
                .map(move |definition| (node, definition))
        })
        .collect::<Vec<_>>();
    for (name, expected_type) in [
        ("multiValue", fluxc::ast::Type::I64),
        ("multiOk", fluxc::ast::Type::Bool),
        ("head", fluxc::ast::Type::I64),
        (
            "middle",
            fluxc::ast::Type::List(Box::new(fluxc::ast::Type::I64)),
        ),
        ("tail", fluxc::ast::Type::I64),
        ("x", fluxc::ast::Type::I64),
        ("y", fluxc::ast::Type::I64),
        ("index", fluxc::ast::Type::I64),
        ("item", fluxc::ast::Type::I64),
        ("payload", fluxc::ast::Type::I64),
    ] {
        let (node, definition) = definitions
            .iter()
            .find(|(_, definition)| definition.name == name)
            .copied()
            .unwrap_or_else(|| panic!("missing CFG definition for {name}"));
        assert_eq!(definition.ty, expected_type, "wrong type for {name}");
        assert_eq!(definition.span.source_id, SourceId::new(1311));
        assert!(
            !graph
                .live_after(node.id)
                .expect("definition node should have liveness")
                .contains(name),
            "compile-time-dead uses should leave {name} dead after its definition"
        );
    }
    assert!(graph.nodes().iter().any(|node| {
        matches!(node.kind, ControlFlowNodeKind::PatternBindings)
            && node
                .definitions
                .iter()
                .any(|definition| definition.name == "payload")
    }));
}

#[test]
fn eliminates_dead_destructure_loop_and_match_extractions() {
    let source = r#"
struct Point {
    x: i64
    y: i64
}

enum Choice {
    Value(i64)
    Empty
}

fn pair() -> (i64, bool) {
    return 41, true
}

fn main() -> i64 {
    let (multiValue, multiOk) = pair()
    let [head, ...middle, tail] = [1, 2, 3]
    let Point { x, y } = Point { x: 4, y: 5 }
    if false:
        print(multiValue)
        print(multiOk)
        print(head)
        print(middle.length)
        print(tail)
        print(x)
        print(y)
    for index, item in [1, 2]:
        if false:
            print(index)
            print(item)
    match Choice.Value(9):
        Choice.Value(payload):
            if false:
                print(payload)
        Choice.Empty():
            print(0)
    return 0
}
"#;

    check_source(source).expect("dead-definition fixture should typecheck");
    let generated = compile_to_c(source).expect("dead definitions should lower natively");
    assert!(generated.contains("flux__fn_pair()"));
    assert!(generated.contains("Flux runtime error: list pattern requires at least 2 elements"));
    assert!(generated.contains("flux__multi_pattern_"));
    assert!(generated.contains("flux__list_pattern_"));
    assert!(generated.contains("flux__destructure_"));
    assert!(generated.contains("flux__range_index_") || generated.contains("flux__iter_index_"));
    for dead_name in [
        "multiValue",
        "multiOk",
        "head",
        "middle",
        "tail",
        "x",
        "y",
        "index",
        "item",
        "payload",
    ] {
        assert!(
            !generated.contains(&format!("flux__local_{dead_name}")),
            "dead definition {dead_name} should not materialize in native code"
        );
    }
}

#[test]
fn semantic_cfg_normalizes_match_guard_evaluation() {
    let source = r#"
enum Choice {
    Value(i64)
    Missing
}

fn classify(choice: Choice, allow: bool) -> i64 {
    match choice:
        Choice.Value(value) if allow:
            return value
        Choice.Value(value):
            return value + 1
        Choice.Missing():
            return 0
}

fn main() -> i64 {
    return classify(Choice.Value(4), true)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1308))
        .expect("guarded match should analyze");
    let graph = database
        .control_flow_graph("classify")
        .expect("guarded match should have a graph");
    let match_node = graph
        .nodes()
        .iter()
        .find(|node| matches!(node.kind, ControlFlowNodeKind::Match))
        .expect("match dispatch should be explicit");
    let value_evaluation = graph
        .incoming(match_node.id)
        .find_map(|edge| graph.node(edge.from))
        .expect("match scrutinee evaluation should precede dispatch");
    assert!(matches!(
        value_evaluation.kind,
        ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::MatchValue)
    ));
    assert_eq!(value_evaluation.ownership.reads, vec!["choice"]);

    let guard = graph
        .nodes()
        .iter()
        .find(|node| {
            matches!(
                node.kind,
                ControlFlowNodeKind::Evaluation(ControlFlowEvaluationKind::MatchGuard(0))
            )
        })
        .expect("guard evaluation should be explicit");
    assert_eq!(guard.value_types, vec![fluxc::ast::Type::Bool]);
    assert_eq!(guard.ownership.reads, vec!["allow"]);
    assert!(
        graph
            .outgoing(guard.id)
            .any(|edge| edge.kind == ControlFlowEdgeKind::GuardTrue)
    );
    assert!(
        graph
            .outgoing(guard.id)
            .any(|edge| edge.kind == ControlFlowEdgeKind::GuardFalse)
    );
}

