#[test]
fn package_import_namespace_loads_declared_path_dependencies() {
    let root = std::env::temp_dir().join(format!(
        "flux-package-import-namespace-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    let app = root.join("app");
    let dependency = root.join("math");
    fs::create_dir_all(app.join("src")).expect("app package should be writable");
    fs::create_dir_all(dependency.join("src")).expect("dependency package should be writable");
    fs::write(
        app.join("flux.toml"),
        "[package]\nname = \"sample-app\"\nentry = \"src/main.flux\"\n\n[dependencies]\nmath_alias = { path = \"../math\", version = \"^1.2.0\" }\n",
    )
    .expect("app manifest should be writable");
    fs::write(
        dependency.join("flux.toml"),
        "[package]\nname = \"flux-math\"\nversion = \"1.4.3\"\nentry = \"src/lib.flux\"\n",
    )
    .expect("dependency manifest should be writable");
    fs::write(
        dependency.join("src/helpers.flux"),
        "pub fn double(value: i64) -> i64 { value * 2 }\n",
    )
    .expect("dependency helper should be writable");
    fs::write(
        dependency.join("src/lib.flux"),
        "import \"helpers.flux\"\npub fn answer() -> i64 { double(21) }\n",
    )
    .expect("dependency entry should be writable");
    fs::write(
        app.join("src/main.flux"),
        "import \"pkg:math_alias/src/lib.flux\"\nfn main() -> i64 { answer() }\n",
    )
    .expect("app entry should be writable");
    fluxc::project::write_lockfile(&app).expect("path dependency lockfile should be writable");

    let (_, sources) = fluxc::project::load(&app).expect("path dependency import should load");
    let module_names = sources
        .iter()
        .map(|source| source.module_name.as_str())
        .collect::<std::collections::HashSet<_>>();
    assert_eq!(
        module_names,
        std::collections::HashSet::from([
            "sample-app::src::main",
            "flux-math::src::lib",
            "flux-math::src::helpers",
        ])
    );
    fluxc::project::check(&app).expect("package dependency imports should typecheck");

    fs::write(
        app.join("flux.toml"),
        "[package]\nname = \"sample-app\"\nentry = \"src/main.flux\"\n\n[dependencies]\nmath_alias = { path = \"../math\", version = \"~2.0.0\" }\n",
    )
    .expect("mismatched dependency requirement should be writable");
    let errors = fluxc::project::check(&app)
        .expect_err("path dependency version outside the requirement must fail");
    assert!(errors.iter().any(|error| {
        error.message.contains("requires version '~2.0.0'")
            && error.message.contains("is version '1.4.3'")
    }));

    fs::write(
        app.join("flux.toml"),
        "[package]\nname = \"sample-app\"\nentry = \"src/main.flux\"\n\n[dependencies]\nmath_alias = { path = \"../math\", version = \"^1.2.0\" }\n",
    )
    .expect("valid dependency manifest should be restorable");
    fluxc::project::write_lockfile(&app).expect("restored dependency lockfile should be writable");
    fs::write(
        app.join("src/main.flux"),
        "import \"pkg:missing/src/lib.flux\"\nfn main() -> i64 { 0 }\n",
    )
    .expect("invalid app entry should be writable");
    let errors = fluxc::project::check(&app).expect_err("undeclared package import must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("package dependency 'missing' is not declared in [dependencies]")
    }));

    fs::write(
        app.join("flux.toml"),
        "[package]\nname = \"sample-app\"\nentry = \"src/main.flux\"\n\n[dependencies]\nremote = \"^1.2.3\"\n",
    )
    .expect("registry manifest should be writable");
    fs::write(
        app.join("src/main.flux"),
        "import \"pkg:remote/src/lib.flux\"\nfn main() -> i64 { 0 }\n",
    )
    .expect("registry app entry should be writable");
    fluxc::project::write_lockfile(&app).expect("registry requirement lockfile should be writable");
    let errors = fluxc::project::check(&app)
        .expect_err("unresolved registry dependency must not pretend to be local");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("package dependency 'remote' requires dependency resolution")
    }));

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn reproducible_lockfile_tracks_transitive_dependency_resolution() {
    let root = std::env::temp_dir().join(format!("flux-package-lockfile-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    let app = root.join("app");
    let math = root.join("math");
    let util = root.join("util");
    for package in [&app, &math, &util] {
        fs::create_dir_all(package.join("src")).expect("package directory should be writable");
    }
    fs::write(
        app.join("flux.toml"),
        "[package]\nname = \"app\"\nentry = \"src/main.flux\"\n\n[dependencies]\nmath = { path = \"../math\", version = \"^1.2.0\" }\nremote = \"~3.4.0\"\nsource = { git = \"https://example.test/source.git\", rev = \"abc123\" }\n",
    )
    .expect("app manifest should be writable");
    fs::write(
        math.join("flux.toml"),
        "[package]\nname = \"math\"\nversion = \"1.4.3\"\nentry = \"src/lib.flux\"\n\n[dependencies]\nutil = { path = \"../util\", version = \"^2.0.0\" }\n",
    )
    .expect("math manifest should be writable");
    fs::write(
        util.join("flux.toml"),
        "[package]\nname = \"util\"\nversion = \"2.0.0\"\nentry = \"src/lib.flux\"\n",
    )
    .expect("util manifest should be writable");
    fs::write(
        app.join("src/main.flux"),
        "import \"pkg:math/src/lib.flux\"\nfn main() -> i64 { answer() }\n",
    )
    .expect("app source should be writable");
    fs::write(
        math.join("src/lib.flux"),
        "import \"pkg:util/src/lib.flux\"\npub fn answer() -> i64 { value() }\n",
    )
    .expect("math source should be writable");
    fs::write(util.join("src/lib.flux"), "pub fn value() -> i64 { 42 }\n")
        .expect("util source should be writable");

    let missing =
        fluxc::project::check(&app).expect_err("dependencies without a lockfile must fail");
    assert!(
        missing
            .iter()
            .any(|error| error.message.contains("require a current flux.lock"))
    );

    let lock = Command::new(env!("CARGO_BIN_EXE_fluxc"))
        .arg("lock")
        .arg(&app)
        .output()
        .expect("flux lock should run");
    assert!(
        lock.status.success(),
        "flux lock failed: {}",
        String::from_utf8_lossy(&lock.stderr)
    );
    let lock_path = app.join("flux.lock");
    assert!(String::from_utf8_lossy(&lock.stdout).contains("locked:"));
    let first = fs::read_to_string(&lock_path).expect("lockfile should be readable");
    assert!(first.contains("version = 1"));
    assert!(first.contains("id = \"math\""));
    assert!(first.contains("package = \"math\""));
    assert!(first.contains("version = \"1.4.3\""));
    assert!(first.contains("source = \"path:../math\""));
    assert!(first.contains("id = \"math/util\""));
    assert!(first.contains("source = \"path:../util\""));
    assert!(first.contains("source = \"registry:~3.4.0\""));
    assert!(first.contains("source = \"git:https://example.test/source.git#abc123\""));

    fluxc::project::write_lockfile(&app).expect("lockfile regeneration should succeed");
    assert_eq!(
        fs::read_to_string(&lock_path).expect("regenerated lockfile should be readable"),
        first,
        "identical dependency inputs must produce byte-identical lockfiles"
    );
    fluxc::project::check(&app).expect("locked path dependency graph should typecheck");

    fs::write(
        util.join("flux.toml"),
        "[package]\nname = \"util\"\nversion = \"2.0.1\"\nentry = \"src/lib.flux\"\n",
    )
    .expect("util version should be writable");
    let stale =
        fluxc::project::check(&app).expect_err("changed dependency metadata must stale the lock");
    assert!(
        stale
            .iter()
            .any(|error| error.message.contains("lockfile") && error.message.contains("stale"))
    );
    fluxc::project::write_lockfile(&app).expect("stale lockfile should refresh deterministically");
    fluxc::project::check(&app).expect("refreshed lockfile should restore the build");

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn semantic_version_resolution_selects_highest_compatible_release() {
    assert_eq!(
        fluxc::project::resolve_semver_requirement(
            "^1.2.3",
            ["1.2.3", "1.9.0", "2.0.0", "1.10.0", "1.10.0+build.7"],
        )
        .expect("caret requirement should resolve"),
        Some("1.10.0".to_string())
    );
    assert_eq!(
        fluxc::project::resolve_semver_requirement("~1.2.3", ["1.2.3", "1.2.9", "1.3.0"])
            .expect("tilde requirement should resolve"),
        Some("1.2.9".to_string())
    );
    assert_eq!(
        fluxc::project::resolve_semver_requirement("^0.2.3", ["0.2.3", "0.2.9", "0.3.0"])
            .expect("zero-major caret requirement should resolve"),
        Some("0.2.9".to_string())
    );
    assert_eq!(
        fluxc::project::resolve_semver_requirement(
            "^1.2.3-beta.1",
            ["1.2.3-beta.1", "1.2.3-beta.2", "1.2.3", "1.3.0-beta.1"],
        )
        .expect("explicit prerelease requirement should resolve"),
        Some("1.2.3".to_string())
    );
    assert_eq!(
        fluxc::project::resolve_semver_requirement("*", ["1.0.0-alpha", "0.9.0", "1.0.0"])
            .expect("wildcard requirement should resolve stable releases"),
        Some("1.0.0".to_string())
    );
    assert!(
        fluxc::project::resolve_semver_requirement("^1.2.3", ["1.2"])
            .expect_err("invalid registry candidate must fail deterministically")
            .contains("invalid SemVer candidate")
    );
}

#[test]
fn accepts_flat_grid_views_without_widget_nesting() {
    let source = r#"
view Dashboard {
    grid columns: 240 1fr 320
    grid rows: 64 1fr
    grid gap: 16
    Text title at 1,2 span columns 2
        text: "Flux dashboard"
    Nav sidebar at 1,1 span rows 2
        label: "Navigation"
    Chart revenue at 2,2
        label: "Revenue"
}

fn main() -> i64 { 42 }
"#;

    let program = fluxc::parser::parse(source).expect("flat grid view should parse");
    assert_eq!(program.views.len(), 1);
    let view = &program.views[0];
    assert_eq!(view.name, "Dashboard");
    assert_eq!(view.grid.columns.len(), 3);
    assert_eq!(view.grid.rows.len(), 2);
    assert_eq!(view.grid.gap, Some(16));
    assert_eq!(view.elements.len(), 3);
    assert_eq!(view.elements[0].name, "title");
    assert_eq!(view.elements[0].column_span, 2);
    assert_eq!(view.elements[1].row_span, 2);
    check_source(source).expect("view declarations must not disturb ordinary type checking");
    let database =
        fluxc::semantic::SemanticDatabase::analyze(source, SourceId::from_name("grid.flux"))
            .expect("view should be available to editor semantics");
    assert!(
        database
            .symbols()
            .iter()
            .any(|symbol| symbol.name == "Dashboard")
    );
    assert!(
        database
            .symbols()
            .iter()
            .any(|symbol| symbol.name == "revenue")
    );
    let generated = compile_to_c(source).expect("views should be zero-runtime metadata for now");
    assert!(generated.contains("int main(void)"));
}

#[test]
fn lowers_app_root_view_to_native_gtk_grid_text_button_and_callback() {
    let source = r#"
fn clicked() -> void {
    print("clicked")
}

view HelloApp {
    grid columns: 1fr
    grid rows: auto auto
    Text title at 1,1
        text: "Hello, Flux!"
    Button action at 2,1
        text: "Click me"
        on_press: clicked
}

app HelloApp
"#;

    check_source(source).expect("zero-parameter app root should typecheck without fn main");
    let program = fluxc::parser::parse(source).expect("application declaration should parse");
    assert_eq!(program.application.as_ref().unwrap().view_name, "HelloApp");
    let generated = compile_to_c(source).expect("Linux app root should lower to GTK4 C");
    assert!(generated.contains("#include <gtk/gtk.h>"));
    assert!(generated.contains("gtk_application_window_new"));
    assert!(generated.contains("gtk_grid_attach"));
    assert!(generated.contains("gtk_grid_set_column_spacing(GTK_GRID(grid), 12)"));
    assert!(generated.contains("gtk_grid_set_row_spacing(GTK_GRID(grid), 12)"));
    assert!(generated.contains("gtk_label_new(\"Hello, Flux!\")"));
    assert!(generated.contains("gtk_button_new_with_label(\"Click me\")"));
    assert!(generated.contains("gtk_widget_set_size_request(flux__ui_action, -1, 40)"));
    assert!(generated.contains("G_CALLBACK(flux__ui_click_action)"));
    assert!(generated.contains("flux__fn_clicked();"));
    assert!(generated.contains("int main(int argc, char **argv)"));
}

#[test]
fn app_view_state_transitions_lower_to_native_state_and_refresh() {
    let source = r##"
view Counter {
    grid columns: 1fr
    grid rows: auto auto auto
    grid padding: 24
    state clicked: bool = false
    Text title at 1,1
        text: "Hello"
        visible: !clicked
        size: 28
        bold: true
        color: "#4F46E5"
    Text status at 2,1
        text: "Clicked!"
        visible: clicked
    Button action at 3,1
        text: "Toggle"
        primary: true
        on_press: clicked => !clicked
}
app Counter
"##;

    check_source(source).expect("typed view state transition should typecheck");
    let program = fluxc::parser::parse(source).expect("stateful app should parse");
    let view = &program.views[0];
    assert_eq!(view.states.len(), 1);
    assert_eq!(view.states[0].name, "clicked");
    let action = view
        .elements
        .iter()
        .find(|element| element.name == "action")
        .and_then(|element| {
            element
                .properties
                .iter()
                .find(|property| property.name == "on_press")
        })
        .expect("button transition should be retained");
    assert_eq!(action.transition.as_ref().unwrap().state, "clicked");

    let formatted = fluxc::formatter::format_source(source).expect("stateful view should format");
    assert!(formatted.contains("grid padding: 24"));
    assert!(formatted.contains("state clicked: bool = false"));
    assert!(formatted.contains("on_press: clicked => !clicked"));

    let generated = compile_to_c(source).expect("stateful Linux app should lower");
    assert!(generated.contains("static bool flux__ui_state_clicked = false;"));
    assert!(generated.contains("flux__ui_state_clicked = (!(flux__ui_state_clicked));"));
    assert!(generated.contains("flux__ui_refresh();"));
    assert!(generated.contains("gtk_label_set_text"));
    assert!(generated.contains("gtk_button_set_label"));
    assert!(generated.contains("gtk_widget_set_margin_top(grid, 24)"));
    assert!(generated.contains("pango_attr_size_new(28 * PANGO_SCALE)"));
    assert!(generated.contains("PANGO_WEIGHT_BOLD"));
    assert!(generated.contains("pango_attr_foreground_new(20303, 17990, 58853)"));
    assert!(generated.contains("gtk_widget_add_css_class(flux__ui_action, \"suggested-action\")"));
    assert!(generated.contains("flux__ui_state_clicked") && generated.contains("Clicked!"));
}

#[test]
fn ui_refresh_tracks_state_and_environment_dependencies() {
    let source = r#"
view Dashboard {
    grid columns: 1fr
    grid rows: auto auto auto auto auto auto
    state count: i64 = 0
    state expanded: bool = false
    derived hasCount: bool = count > 0
    Text countLabel at 1,1
        text: "Count"
        visible: hasCount
    Text panel at 2,1
        text: "Panel"
        visible: expanded
    Text widthLabel at 3,1
        text: "Wide"
        visible: windowWidth > 500
    Text staticLabel at 4,1
        text: "Static"
    Button increment at 5,1
        text: "Increment"
        onPress: count => count + 1
    Button toggle at 6,1
        text: "Toggle"
        onPress: expanded => !expanded
}
app Dashboard
"#;

    check_source(source).expect("dependency-tracked view should typecheck");
    let generated = compile_to_c(source).expect("dependency-tracked view should lower natively");
    assert!(generated.contains("static void flux__ui_refresh_changed(int changed_state)"));
    assert!(
        generated
            .contains("if (changed_state == -1 || changed_state == 0) flux__ui_derived_hasCount")
    );
    assert!(generated.contains(
        "if (changed_state == -1 || changed_state == 0) {\n    if (flux__ui_countLabel != NULL) gtk_widget_set_visible"
    ));
    assert!(generated.contains(
        "if (changed_state == -1 || changed_state == 1) {\n    if (flux__ui_panel != NULL) gtk_widget_set_visible"
    ));
    assert!(generated.contains(
        "if (changed_state < 0) {\n    if (flux__ui_widthLabel != NULL) gtk_widget_set_visible"
    ));
    assert!(generated.contains("if (changed_state == -1) {\n    if (flux__ui_staticLabel"));
    assert!(generated.contains("flux__ui_refresh_changed(0);"));
    assert!(generated.contains("flux__ui_refresh_changed(1);"));
    assert!(generated.contains("flux__ui_refresh_changed(-2);"));
}

