#[test]
fn accessibility_order_lowers_to_native_assistive_reading_order() {
    let source = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto auto auto
    Text third at 1,1
        text: "Third"
        accessibilityOrder: 30
    Button first at 2,1
        text: "First"
        accessibilityOrder: 10
    TextInput second at 3,1
        accessibilityOrder: 20
}
app Screen
"#;
    check_source(source).expect("unique compile-time accessibility order should typecheck");
    let linux = compile_to_c(source).expect("accessibility order should lower to GTK relations");
    assert!(linux.contains("GTK_ACCESSIBLE_RELATION_FLOW_TO, GTK_ACCESSIBLE(flux__ui_second), -1"));
    assert!(linux.contains("GTK_ACCESSIBLE_RELATION_FLOW_TO, GTK_ACCESSIBLE(flux__ui_third), -1"));
    let first_to_second = linux
        .find("GTK_ACCESSIBLE(flux__ui_first), GTK_ACCESSIBLE_RELATION_FLOW_TO, GTK_ACCESSIBLE(flux__ui_second)")
        .expect("first should flow to second");
    let second_to_third = linux
        .find("GTK_ACCESSIBLE(flux__ui_second), GTK_ACCESSIBLE_RELATION_FLOW_TO, GTK_ACCESSIBLE(flux__ui_third)")
        .expect("second should flow to third");
    assert!(first_to_second < second_to_third);

    let program = fluxc::parser::parse(source).expect("accessibility-order app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("accessibility-order app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("accessibility order should lower to Android traversal metadata");
    assert!(android.contains("setAccessibilityTraversalAfter"));
    assert!(android.contains(&format!(
        "set_accessibility_traversal_after, (jint){}",
        android_stable_view_id("Screen", "first")
    )));
    assert!(android.contains(&format!(
        "set_accessibility_traversal_after, (jint){}",
        android_stable_view_id("Screen", "second")
    )));

    let duplicate = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Text first at 1,1
        accessibilityOrder: 1
    Text second at 2,1
        accessibilityOrder: 1
}
app Screen
"#;
    let errors = check_source_all(duplicate).expect_err("duplicate accessibility order must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("accessibilityOrder 1 is already used")
    }));

    let dynamic = r#"
view Screen {
    state order: i64 = 1
    grid columns: 1fr
    grid rows: auto
    Text item at 1,1
        accessibilityOrder: order
}
app Screen
"#;
    let errors = check_source_all(dynamic).expect_err("runtime accessibility order must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("accessibilityOrder must be a compile-time i64 value")
    }));
}

#[test]
fn native_controls_preserve_platform_screen_reader_bridges() {
    let source = r#"
view Screen {
    state semanticValue: str = "Off"
    grid columns: 1fr
    grid rows: auto auto auto auto auto auto
    Text title at 1,1
        text: "Title"
        accessibilityLabel: "Screen title"
        accessibilityRole: "heading"
        accessibilityOrder: 10
    Button action at 2,1
        text: "Continue"
        accessibilityDescription: "Continue to the next step"
        accessibilityRole: "button"
        accessibilityOrder: 20
    TextInput input at 3,1
        accessibilityLabel: "Name"
        accessibilityRole: "textBox"
        accessibilityOrder: 30
    Toggle toggle at 4,1
        label: "Enabled"
        accessibilityLabel: "Enabled setting"
        accessibilityValue: semanticValue
        accessibilityRole: "switch"
        accessibilityOrder: 40
    Radio radio at 5,1
        label: "Choice"
        accessibilityLabel: "Choice option"
        accessibilityRole: "radio"
        accessibilityOrder: 50
    Image image at 6,1
        source: ""
        alt: "Preview"
        accessibilityLabel: "Preview image"
        accessibilityRole: "image"
        accessibilityHidden: false
        accessibilityOrder: 60
}
app Screen
"#;

    check_source(source).expect("native accessibility bridge sample should typecheck");
    let linux =
        compile_to_c(source).expect("native accessibility bridge sample should lower on Linux");
    assert!(linux.contains("gtk_label_new"));
    assert!(linux.contains("gtk_button_new_with_label"));
    assert!(linux.contains("gtk_entry_new"));
    assert!(linux.contains("gtk_check_button_new_with_label"));
    assert!(linux.contains("gtk_picture_new"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_LABEL"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_DESCRIPTION"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_VALUE_TEXT"));
    assert!(
        linux.matches("GTK_ACCESSIBLE_PROPERTY_VALUE_TEXT").count() >= 2,
        "state-driven accessibility values should lower for initial render and refresh"
    );
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_ROLE_DESCRIPTION"));
    assert!(linux.contains("GTK_ACCESSIBLE_STATE_HIDDEN"));
    assert!(linux.contains("GTK_ACCESSIBLE_RELATION_FLOW_TO"));

    let program = fluxc::parser::parse(source).expect("screen-reader bridge app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("screen-reader bridge app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("native accessibility bridge sample should lower on Android");
    for class_name in [
        "android/widget/TextView",
        "android/widget/Button",
        "app/flux/runtime/FluxActivity$FluxEditText",
        "android/widget/Switch",
        "android/widget/RadioButton",
        "android/widget/ImageView",
    ] {
        assert!(
            android.contains(class_name),
            "missing native Android accessibility-bearing control {class_name}"
        );
    }
    assert!(android.contains("setAccessibility"));
    assert!(android.contains("setAccessibilityValue"));
    assert!(
        android.matches("setAccessibilityValue").count() >= 2,
        "state-driven Android accessibility values should lower for initial render and refresh"
    );
    assert!(android.contains("setAccessibilityRole"));
    assert!(android.contains("setAccessibilityHidden"));
    assert!(android.contains("setAccessibilityTraversalAfter"));
}

