#[test]
fn native_elements_support_explicit_keyboard_focusability() {
    let source = r#"
fn key_notice(key: str) -> void {
    print(key)
}

view KeyCard {
    state keyboardEnabled: bool = false
    grid columns: 1fr
    grid rows: auto auto auto
    Text title at 1,1
        text: "Keyboard target"
        focusable: keyboardEnabled
        onKey: key_notice
    Button action at 2,1
        text: "Mouse only"
        focusable: false
    Toggle launch at 3,1
        label: "Initial focus"
        autofocus: true
}
app KeyCard
"#;

    check_source(source).expect("common focusable state should typecheck on native elements");
    let linux = compile_to_c(source).expect("focusable should lower to GTK4");
    assert!(
        linux.contains("gtk_widget_set_focusable(flux__ui_title, flux__ui_state_keyboardEnabled)")
    );
    assert!(linux.contains("gtk_widget_set_focusable(flux__ui_action, false)"));
    assert!(!linux.contains("gtk_widget_set_focusable(flux__ui_title, TRUE)"));
    assert!(linux.contains("gtk_widget_set_focusable(flux__ui_launch, TRUE)"));
    assert!(linux.contains("gtk_widget_grab_focus(flux__ui_launch)"));

    let program = fluxc::parser::parse(source).expect("focusable Android app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("focusable Android app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("focusable should lower to Android Views");
    assert!(android.contains("\"setFocusable\", \"(Z)V\""));
    assert!(android.contains("\"setFocusableInTouchMode\", \"(Z)V\""));
    assert!(android.contains("(jboolean)(flux__ui_state_keyboardEnabled)"));
    assert!(android.contains("refresh_focusable"));
    assert!(android.contains("if (changed_state == -1 || changed_state == 0) {"));
    assert!(!android.contains("set_focusable, (jboolean)true"));
    assert!(android.contains("request_autofocus"));
    assert!(android.contains("autofocus_focusable"));

    let invalid = r#"
view BadFocus {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        focusable: "yes"
}
app BadFocus
"#;
    let errors =
        check_source_all(invalid).expect_err("focusable must remain a typed bool property");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("property 'Text.focusable'"))
    );

    let ambiguous = r#"
view AmbiguousFocus {
    grid columns: 1fr
    grid rows: auto auto
    Button first at 1,1
        text: "First"
        autofocus: true
    Button second at 2,1
        text: "Second"
        autofocus: true
}
app AmbiguousFocus
"#;
    let errors = check_source_all(ambiguous).expect_err("a view must have one autofocus target");
    assert!(errors.iter().any(|error| {
        error.message.contains("more than one autofocus target") && error.message.contains("first")
    }));

    let contradictory = r#"
view ContradictoryFocus {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "No focus"
        focusable: false
        autofocus: true
}
app ContradictoryFocus
"#;
    let errors = check_source_all(contradictory)
        .expect_err("autofocus must not contradict explicit focusability");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("autofocus: true requires focusable: true")
    }));

    let custom_property = r#"
view Badge(autofocus: bool) {
    grid columns: 1fr
    grid rows: auto
    Text label at 1,1
        text: "Badge"
}
view CustomFocusNames {
    grid columns: 1fr
    grid rows: auto auto
    Badge first at 1,1
        autofocus: true
    Badge second at 2,1
        autofocus: true
}
app CustomFocusNames
"#;
    check_source(custom_property)
        .expect("custom view parameters named autofocus must not use built-in focus validation");
}

#[test]
fn native_elements_support_hover_leave_callbacks_and_state_transitions() {
    let source = r#"
fn leave_notice() -> void {
    print("left")
}

fn tapped() -> void {
    print("tapped")
}

fn dragged(_offsetX: i64, _offsetY: i64) -> void {
}

fn swiped(_velocityX: i64, _velocityY: i64) -> void {
}

fn scaled(_scalePercent: i64) -> void {
}

view HoverCard {
    grid columns: 1fr
    grid rows: auto auto
    state hovered: bool = false
    Text title at 1,1
        text: "Hover state"
        tooltip: "Hover me"
        accessibility_label: "Hover state title"
        visible: hovered
        onTap: tapped
        onDoubleTap: tapped
        onLongPress: hovered => true
        onDrag: dragged
        onSwipe: swiped
        onScale: scaled
        on_hover: hovered => true
        on_leave: hovered => false
    Button action at 2,1
        text: "Action"
        on_focus: hovered => true
        on_blur: leave_notice
        on_leave: leave_notice
}
app HoverCard
"#;

    check_source(source).expect("hover/leave callbacks and transitions should typecheck");
    let generated = compile_to_c(source).expect("hover/leave events should lower natively");
    assert!(generated.contains("GtkEventControllerMotion *controller"));
    assert!(generated.contains("GtkGestureClick *gesture"));
    assert!(generated.contains("flux__fn_tapped(); flux__ui_refresh();"));
    assert!(generated.contains("gtk_button_new()"));
    assert!(
        generated.contains("gtk_button_set_has_frame(GTK_BUTTON(flux__ui_action_title), FALSE)")
    );
    assert!(
        generated
            .contains("gtk_button_set_child(GTK_BUTTON(flux__ui_action_title), flux__ui_title)")
    );
    assert!(generated.contains("g_signal_connect(flux__ui_action_title, \"clicked\", G_CALLBACK(flux__ui_activate_title), NULL)"));
    assert!(generated.contains("flux__ui_double_tap_title"));
    assert!(generated.contains("if (n_press != 2) return; flux__fn_tapped(); flux__ui_refresh();"));
    assert!(generated.contains("\"released\", G_CALLBACK(flux__ui_double_tap_title)"));
    assert!(
        generated
            .contains("gtk_widget_add_controller(flux__ui_action_title, flux__double_tap_title)")
    );
    assert!(!generated.contains("flux__ui_tap_key_title"));
    assert!(generated.contains("GtkGestureLongPress *gesture"));
    assert!(generated.contains("gtk_gesture_long_press_new()"));
    assert!(generated.contains("GtkGestureDrag *gesture"));
    assert!(generated.contains("gtk_gesture_drag_new()"));
    assert!(generated.contains("\"drag-update\", G_CALLBACK(flux__ui_drag_title)"));
    assert!(generated.contains("GtkGestureSwipe *gesture"));
    assert!(generated.contains("gtk_gesture_swipe_new()"));
    assert!(generated.contains("\"swipe\", G_CALLBACK(flux__ui_swipe_title)"));
    assert!(generated.contains("GtkGestureZoom *gesture"));
    assert!(generated.contains("gtk_gesture_zoom_new()"));
    assert!(generated.contains("\"scale-changed\", G_CALLBACK(flux__ui_scale_title)"));
    assert!(
        generated.contains("flux__fn_scaled((int64_t)(scale * 100.0 + 0.5)); flux__ui_refresh();")
    );
    assert!(
        generated.contains(
            "flux__fn_dragged((int64_t)offset_x, (int64_t)offset_y); flux__ui_refresh();"
        )
    );
    assert!(generated.contains(
        "flux__fn_swiped((int64_t)velocity_x, (int64_t)velocity_y); flux__ui_refresh();"
    ));
    assert!(generated.contains("\"pressed\", G_CALLBACK(flux__ui_long_press_title)"));
    assert!(
        generated
            .contains("gtk_widget_add_controller(flux__ui_action_title, flux__long_press_title)")
    );
    assert!(generated.contains("flux__ui_state_hovered = true; flux__ui_refresh_changed(0);"));
    assert!(generated.contains("flux__ui_state_hovered = false; flux__ui_refresh_changed(0);"));
    assert!(generated.contains("flux__fn_leave_notice(); flux__ui_refresh();"));
    assert!(generated.contains("gtk_widget_set_tooltip_text(flux__ui_action_title, \"Hover me\")"));
    assert!(generated.contains("GTK_ACCESSIBLE(flux__ui_action_title), GTK_ACCESSIBLE_PROPERTY_LABEL, \"Hover state title\", -1"));
    assert!(
        generated.contains("gtk_widget_set_visible(flux__ui_action_title, flux__ui_state_hovered)")
    );
    assert!(generated.contains("gtk_event_controller_motion_new()"));
    assert!(generated.contains("gtk_event_controller_focus_new()"));
    assert!(generated.contains("\"enter\", G_CALLBACK(flux__ui_focus_action)"));
    assert!(generated.contains("\"leave\", G_CALLBACK(flux__ui_blur_action)"));
    assert!(generated.contains("\"enter\", G_CALLBACK(flux__ui_hover_title)"));
    assert!(generated.contains("\"leave\", G_CALLBACK(flux__ui_leave_title)"));
    assert!(
        generated.contains("gtk_widget_add_controller(flux__ui_action_title, flux__motion_title)")
    );
}

#[test]
fn portable_context_menu_requests_use_native_secondary_or_long_press_gestures() {
    let source = r#"
view ContextCard {
    grid columns: 1fr
    grid rows: auto
    state opened: bool = false
    state selected: bool = false
    Text card at 1,1
        text: "Options"
        visible: selected
        onContextMenu: opened => true
        contextMenuLabel: "Open"
        onContextMenuSelect: selected => true
}
app ContextCard
"#;

    check_source(source).expect("context-menu requests and state transitions should typecheck");
    let linux = compile_to_c(source).expect("context-menu requests should lower to GTK");
    assert!(linux.contains("flux__ui_context_menu_card"));
    assert!(linux.contains("gtk_gesture_single_set_button(GTK_GESTURE_SINGLE(flux__context_menu_card), GDK_BUTTON_SECONDARY)"));
    assert!(linux.contains("\"released\", G_CALLBACK(flux__ui_context_menu_card)"));
    assert!(linux.contains("gtk_button_new_with_label(\"Open\")"));
    assert!(linux.contains("gtk_popover_set_pointing_to"));
    assert!(linux.contains("G_CALLBACK(flux__ui_context_menu_select_card)"));
    assert!(linux.contains("flux__ui_context_menu_key_card"));
    assert!(linux.contains("keyval != GDK_KEY_Menu"));
    assert!(linux.contains("keyval == GDK_KEY_F10 && (state & GDK_SHIFT_MASK)"));
    assert!(linux.contains("gtk_widget_set_focusable(flux__ui_card, TRUE)"));
    assert!(linux.contains("flux__ui_state_opened = true; flux__ui_refresh_changed(0);"));
    assert!(linux.contains("flux__ui_state_selected = true; flux__ui_refresh_changed(1);"));

    let program = fluxc::parser::parse(source).expect("context-menu app should parse");
    let signatures = fluxc::typecheck::check(&program).expect("context-menu app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("context-menu requests should lower to Android long-click activation");
    assert!(android.contains("setOnLongClickListener"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeOnContextMenu"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeOnContextMenuSelect"));
    assert!(android.contains("setContextMenuEnabled"));
    assert!(android.contains("setContextMenuLabel"));
    assert!(android.contains("context_menu_set_focusable"));
    assert!(android.contains("NewStringUTF(env, \"Open\")"));
    assert!(android.contains(
        "flux__ui_state_opened = true; if (flux__android_activity != NULL) flux__android_ui_refresh(env, flux__android_activity->clazz, 0);"
    ));
    assert!(android.contains(
        "flux__ui_state_selected = true; if (flux__android_activity != NULL) flux__android_ui_refresh(env, flux__android_activity->clazz, 1);"
    ));

    let multi_item = r#"
fn menuSelected(index: i64) -> void {
    print(index)
}
view ContextCard {
    grid columns: 1fr
    grid rows: auto
    Text card at 1,1
        text: "Options"
        contextMenuItems: ["Open", "Archive", "Delete"]
        onContextMenuItemSelect: menuSelected
}
app ContextCard
"#;
    check_source(multi_item).expect("multi-item context menus should typecheck");
    let linux = compile_to_c(multi_item).expect("multi-item context menus should lower to GTK");
    assert!(linux.contains("gtk_box_new(GTK_ORIENTATION_VERTICAL, 0)"));
    assert!(linux.contains("gtk_button_new_with_label(\"Open\")"));
    assert!(linux.contains("gtk_button_new_with_label(\"Archive\")"));
    assert!(linux.contains("gtk_button_new_with_label(\"Delete\")"));
    assert!(
        linux.contains("GPOINTER_TO_INT(g_object_get_data(G_OBJECT(button), \"flux-menu-index\"))")
    );
    assert!(linux.contains("flux__fn_menuSelected((int64_t)item_index); flux__ui_refresh();"));

    let program =
        fluxc::parser::parse(multi_item).expect("multi-item context menu app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("multi-item context menu app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("multi-item context menus should lower to Android PopupMenu");
    assert!(android.contains("setContextMenuItems"));
    assert!(android.contains("NewObjectArray(env, 3, context_menu_string_class, NULL)"));
    assert!(android.contains("NewStringUTF(env, \"Open\")"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeOnContextMenuItemSelect"));
    assert!(android.contains("flux__fn_menuSelected((int64_t)item_index)"));

    let invalid_items = r#"
fn menuSelected(index: i64) -> void {
    print(index)
}
view ContextCard {
    grid columns: 1fr
    grid rows: auto
    Text card at 1,1
        text: "Options"
        contextMenuItems: []
        onContextMenuItemSelect: menuSelected
}
app ContextCard
"#;
    let errors = check_source_all(invalid_items)
        .expect_err("context menu item lists must contain at least one label");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("contextMenuItems must contain at least one menu label")
    }));

    let conflicting = r#"
fn action() -> void {
    print("action")
}
view ContextCard {
    grid columns: 1fr
    grid rows: auto
    Text card at 1,1
        text: "Options"
        onLongPress: action
        onContextMenu: action
}
app ContextCard
"#;
    let errors = check_source_all(conflicting)
        .expect_err("Android long-click semantics require one long-press/context action");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("onContextMenu cannot be combined with onLongPress")
    }));

    let incomplete = r#"
fn action() -> void {
    print("action")
}
view ContextCard {
    grid columns: 1fr
    grid rows: auto
    Text card at 1,1
        text: "Options"
        contextMenuLabel: "Open"
}
app ContextCard
"#;
    let errors = check_source_all(incomplete)
        .expect_err("presented context-menu actions require a selection callback");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("contextMenuLabel requires onContextMenuSelect")
    }));
}

#[test]
fn portable_text_drag_and_drop_uses_native_platform_drag_surfaces() {
    let source = r#"
fn dropped(value: str) -> void {
    print(value)
}

view DragDrop {
    grid columns: 1fr
    grid rows: auto auto
    Text source at 1,1
        text: "Drag me"
        dragText: "horse-profile"
    Text target at 2,1
        text: "Drop here"
        onDrop: dropped
}
app DragDrop
"#;

    check_source(source).expect("portable text drag/drop should typecheck");
    let linux = compile_to_c(source).expect("portable text drag/drop should lower to GTK");
    assert!(linux.contains("gdk_content_provider_new_typed(G_TYPE_STRING, \"horse-profile\")"));
    assert!(linux.contains("gtk_drag_source_new()"));
    assert!(
        linux.contains("gtk_drag_source_set_actions(flux__drag_source_source, GDK_ACTION_COPY)")
    );
    assert!(linux.contains("gtk_drop_target_new(G_TYPE_STRING, GDK_ACTION_COPY)"));
    assert!(linux.contains("G_CALLBACK(flux__ui_drop_target)"));
    assert!(linux.contains("const char *text = g_value_get_string(value)"));
    assert!(linux.contains("flux__fn_dropped(text); flux__ui_refresh();"));

    let program = fluxc::parser::parse(source).expect("drag/drop app should parse");
    let signatures = fluxc::typecheck::check(&program).expect("drag/drop app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("portable text drag/drop should lower to Android");
    assert!(android.contains("setOnLongClickListener"));
    assert!(android.contains("setDragText"));
    assert!(android.contains("NewStringUTF(env, \"horse-profile\")"));
    assert!(android.contains("setOnDragListener"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeOnDrop"));
    assert!(android.contains("flux__fn_dropped(value); flux__ui_refresh();"));

    let wrong_callback = r#"
fn dropped(_value: i64) -> void {
}
view DragDrop {
    grid columns: 1fr
    grid rows: auto
    Text target at 1,1
        text: "Drop"
        onDrop: dropped
}
app DragDrop
"#;
    let errors = check_source_all(wrong_callback)
        .expect_err("onDrop must require an exact fn(str) -> void callback");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("expected fn(str) -> void"))
    );

    let dynamic_payload = r#"
view DragDrop {
    grid columns: 1fr
    grid rows: auto
    state payload: str = "horse"
    Text source at 1,1
        text: "Drag"
        dragText: payload
}
app DragDrop
"#;
    let errors = check_source_all(dynamic_payload)
        .expect_err("dragText is intentionally stable compile-time drag metadata");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("dragText must be a compile-time string value")
    }));

    let conflicting = r#"
fn opened() -> void {
}
view DragDrop {
    grid columns: 1fr
    grid rows: auto
    Text source at 1,1
        text: "Drag"
        dragText: "horse"
        onLongPress: opened
}
app DragDrop
"#;
    let errors = check_source_all(conflicting)
        .expect_err("Android cannot assign the same long-click to drag start and long press");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("dragText cannot be combined with long-press/context-menu activation")
    }));
}

#[test]
fn passive_tap_actions_use_native_accessible_activation() {
    let source = r#"
fn tapped() -> void {
    print("tapped")
}

fn keyed(key: str) -> void {
    print(key)
}

view Actions {
    grid columns: 1fr
    grid rows: auto auto
    Text title at 1,1
        text: "Open details"
        accessibilityLabel: "Open details"
        onTap: tapped
        onKey: keyed
    Image artwork at 2,1
        source: ""
        alt: "Preview"
        accessibilityLabel: "Open preview"
        onTap: tapped
}
app Actions
"#;

    check_source(source).expect("portable passive activation should typecheck");
    let linux =
        compile_to_c(source).expect("passive activation should lower to native GTK actions");
    for (host, child, callback) in [
        (
            "flux__ui_action_title",
            "flux__ui_title",
            "flux__ui_activate_title",
        ),
        (
            "flux__ui_action_artwork",
            "flux__ui_artwork",
            "flux__ui_activate_artwork",
        ),
    ] {
        assert!(linux.contains(&format!("{host} = gtk_button_new()")));
        assert!(linux.contains(&format!(
            "gtk_button_set_has_frame(GTK_BUTTON({host}), FALSE)"
        )));
        assert!(linux.contains(&format!(
            "gtk_button_set_child(GTK_BUTTON({host}), {child})"
        )));
        assert!(linux.contains(&format!(
            "g_signal_connect({host}, \"clicked\", G_CALLBACK({callback}), NULL)"
        )));
    }
    assert!(linux.contains(
        "GTK_ACCESSIBLE(flux__ui_action_title), GTK_ACCESSIBLE_PROPERTY_LABEL, \"Open details\", -1"
    ));
    assert!(linux.contains("GTK_ACCESSIBLE(flux__ui_action_artwork), GTK_ACCESSIBLE_PROPERTY_LABEL, \"Open preview\", -1"));
    assert!(!linux.contains("flux__ui_tap_key_title"));
    assert!(linux.contains("if (keyval == GDK_KEY_Return || keyval == GDK_KEY_KP_Enter || keyval == GDK_KEY_space) return TRUE;"));

    let program = fluxc::parser::parse(source).expect("passive action app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("passive action app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("passive actions should lower to Android native click actions");
    assert!(android.contains("setOnClickListener"));
    assert!(android.contains("setFocusable"));
}

