#[test]
fn android_native_document_pickers_are_typed_direct_and_tree_shaken() {
    let source = r#"
fn selected(uri: str) -> void {
    print(uri)
}
fn started() -> void {
    android.pickFile(selected)
    android.pickMedia(selected)
    android.pickDirectory(selected)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onStart: started)
"#;

    check_source(source).expect("Android native pickers should typecheck");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
        .expect("Android picker app should analyze");
    let generated = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("Android native pickers should lower directly");
    assert!(generated.contains("static inline void flux__android_pick_file"));
    assert!(generated.contains("static inline void flux__android_pick_media"));
    assert!(generated.contains("static inline void flux__android_pick_directory"));
    assert!(generated.contains("static void flux__android_launch_picker"));
    assert!(generated.contains("\"fluxPickFile\", callback, 1"));
    assert!(generated.contains("\"fluxPickMedia\", callback, 2"));
    assert!(generated.contains("\"fluxPickDirectory\", callback, 3"));
    assert!(generated.contains("Java_app_flux_runtime_FluxActivity_nativeOnPickerResult"));
    assert!(generated.contains("callback(value);"));
    assert!(generated.contains("ReleaseStringUTFChars"));
    assert!(!generated.contains("MethodChannel"));
    assert!(!generated.contains("plugin registry"));

    let error = compile_to_c(source).expect_err("Android pickers must reject the Linux target");
    assert!(
        error
            .message
            .contains("android.* platform APIs require the Android target")
    );

    let unused = r#"
fn selected(uri: str) -> void {
    print(uri)
}
fn unused() -> void {
    android.pickFile(selected)
    android.pickMedia(selected)
    android.pickDirectory(selected)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(unused, SourceId::UNKNOWN)
        .expect("unreachable picker app should analyze");
    let tree_shaken = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("unreachable Android picker code should tree-shake");
    assert!(!tree_shaken.contains("flux__android_pick_file("));
    assert!(!tree_shaken.contains("flux__android_pick_media("));
    assert!(!tree_shaken.contains("flux__android_pick_directory("));
    assert!(!tree_shaken.contains("nativeOnPickerResult"));

    let invalid = r#"
fn wrong(value: i64) -> void {
    print(value)
}
fn main() -> i64 {
    android.pickFile(wrong)
    android.pickMedia(42)
    android.pickDirectory()
    return 0
}
"#;
    let errors = check_source_all(invalid).expect_err("Android picker callbacks must be typed");
    assert!(errors.iter().any(|error| {
        error.message.contains("android.pickFile callback")
            && error.message.contains("expected fn(str) -> void")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("android.pickMedia callback")
            && error.message.contains("expected fn(str) -> void")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("android.pickDirectory expects 1 argument, got 0")
    }));
}

#[test]
fn android_background_jobs_use_native_job_scheduler_with_compiler_owned_callback() {
    let source = r#"
fn background(jobId: i64) -> void {
    print(jobId)
}
fn started() -> void {
    print(android.scheduleBackgroundJob(7, 1000))
    android.cancelBackgroundJob(8)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onStart: started, onBackgroundJob: background)
"#;

    check_source(source).expect("Android background jobs should typecheck");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
        .expect("Android background job app should analyze");
    let generated = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("Android background jobs should lower directly");
    assert!(generated.contains("static bool flux__android_schedule_background_job"));
    assert!(generated.contains("static void flux__android_cancel_background_job"));
    assert!(generated.contains("app/flux/runtime/FluxJobService"));
    assert!(generated.contains("Java_app_flux_runtime_FluxJobService_nativeRunJob"));
    assert!(generated.contains("flux__fn_background((int64_t)job_id);"));
    assert!(!generated.contains("MethodChannel"));
    assert!(!generated.contains("plugin registry"));

    let error = compile_to_c(source).expect_err("Android background jobs must reject Linux");
    assert!(
        error
            .message
            .contains("android.* platform APIs require the Android target")
    );

    let missing_callback = r#"
fn started() -> void {
    print(android.scheduleBackgroundJob(7, 1000))
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onStart: started)
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(missing_callback, SourceId::UNKNOWN)
        .expect("background job fixture without callback should analyze before codegen");
    let error = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect_err("scheduled jobs without an application callback must fail");
    assert!(error.message.contains(
        "android.scheduleBackgroundJob requires application onBackgroundJob: fn(i64) -> void callback"
    ));

    let invalid = r#"
fn badBackground(value: str) -> void {
    print(value)
}
fn main() -> i64 {
    print(android.scheduleBackgroundJob("job", false))
    android.cancelBackgroundJob("job")
    return 0
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onBackgroundJob: badBackground)
"#;
    let errors =
        check_source_all(invalid).expect_err("Android background job contracts must be typed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("android.scheduleBackgroundJob jobId")
            && error.message.contains("expected i64")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("android.cancelBackgroundJob jobId")
            && error.message.contains("expected i64")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("application onBackgroundJob callback")
            && error.message.contains("expected fn(i64) -> void")
    }));

    let unused = r#"
fn background(jobId: i64) -> void {
    print(jobId)
}
fn unused() -> void {
    print(android.scheduleBackgroundJob(7, 1000))
    android.cancelBackgroundJob(7)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onBackgroundJob: background)
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(unused, SourceId::UNKNOWN)
        .expect("unreachable background job app should analyze");
    let tree_shaken = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("unreachable Android background job code should tree-shake");
    assert!(!tree_shaken.contains("flux__android_schedule_background_job("));
    assert!(!tree_shaken.contains("flux__android_cancel_background_job("));
}

#[test]
fn android_native_ui_lowers_flat_grid_text_button_and_click_dispatch() {
    let root = std::env::temp_dir().join(format!("flux-android-ui-codegen-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("src")).expect("Android UI fixture should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"native-ui\"\nentry = \"src/main.flux\"\n",
    )
    .expect("Android UI manifest should be writable");
    fs::write(
        root.join("src/main.flux"),
        r#"fn pressed() -> void {
    print("pressed")
}
view Screen {
    state expanded: bool = false
    derived label: str = "Toggle"
    grid columns: 1fr
    grid rows: auto auto auto
    Text title at 1,1
        text: "Hello Android"
        visible: expanded
    Button toggle at 2,1
        text: label
        onPress: expanded => !expanded
    Button action at 3,1
        text: "Press"
        enabled: !expanded && window_is_medium
        primary: true
        onPress: pressed
}
app Screen
"#,
    )
    .expect("Android UI source should be writable");

    let analysis = fluxc::project::analyze(&root).expect("Android UI app should analyze");
    let generated = analysis
        .emit_c_for_target(fluxc::codegen::NativeTarget::Android)
        .expect("Android UI app should lower to target C");
    assert!(generated.contains("Java_app_flux_runtime_FluxActivity_nativeBuildUi"));
    assert!(generated.contains("Java_app_flux_runtime_FluxActivity_nativeRefreshUi"));
    assert!(generated.contains("findViewById"));
    let title_id = android_stable_view_id("Screen", "title");
    let toggle_id = android_stable_view_id("Screen", "toggle");
    let action_id = android_stable_view_id("Screen", "action");
    assert!(generated.contains(&format!("find_view, (jint){title_id}")));
    assert!(!generated.contains(&format!("find_view, (jint){toggle_id}")));
    assert!(generated.contains(&format!("find_view, (jint){action_id}")));
    assert!(generated.contains("set_stable_id"));
    assert!(generated.contains("android/widget/GridLayout"));
    assert!(generated.contains("android/widget/TextView"));
    assert!(generated.contains("android/widget/Button"));
    assert!(generated.contains("INT64_C(48) * flux__ui_density"));
    assert!(generated.contains("INT64_C(6) * flux__ui_density"));
    assert!(generated.contains("setOnClickListener"));
    assert!(generated.contains("styleButton"));
    assert!(generated.contains("(Landroid/widget/Button;Z)V"));
    assert!(generated.contains("style_button, child, JNI_FALSE"));
    assert!(generated.contains("style_button, child, JNI_TRUE"));
    assert!(generated.contains("Java_app_flux_runtime_FluxActivity_nativeOnClick"));
    assert!(generated.contains("static bool flux__ui_state_expanded = false;"));
    assert!(generated.contains("static const char * flux__ui_derived_label = NULL;"));
    assert!(generated.contains("flux__ui_window_width"));
    assert!(generated.contains("getDisplayMetrics"));
    assert!(generated.contains("\"density\", \"F\""));
    assert!(generated.contains("static float flux__ui_density = 1.0f;"));
    assert!(generated.contains("(float)width / flux__ui_density"));
    assert!(generated.contains("(float)height / flux__ui_density"));
    assert!(
        generated.contains(
            "flux__ui_window_width >= INT64_C(600) && flux__ui_window_width < INT64_C(840)"
        )
    );
    assert!(generated.contains("setVisibility"));
    assert!(generated.contains("setEnabled"));
    assert!(generated.contains("flux__ui_state_expanded = (!(flux__ui_state_expanded))"));
    assert!(generated.contains(&format!(
        "case {toggle_id}: flux__ui_state_expanded = (!(flux__ui_state_expanded)); if (flux__android_activity != NULL) flux__android_ui_refresh(env, flux__android_activity->clazz, 0); break;"
    )));
    assert!(generated.contains(&format!("case {action_id}: flux__fn_pressed(); break;")));
    assert!(generated.contains(
        "activity->callbacks->onConfigurationChanged = flux__android_on_configuration_changed"
    ));
    assert!(!generated.contains("#include <gtk/gtk.h>"));

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn android_native_view_ids_survive_reordering_and_insertions() {
    let root = std::env::temp_dir().join(format!(
        "flux-android-stable-view-id-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("src")).expect("Android stable-ID fixture should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"stable-ui\"\nentry = \"src/main.flux\"\n",
    )
    .expect("Android stable-ID manifest should be writable");

    let first_source = r#"fn pressed() -> void {
    print("pressed")
}
view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Text title at 1,1
        text: "Title"
    Button action at 2,1
        text: "Press"
        onPress: pressed
}
app Screen
"#;
    fs::write(root.join("src/main.flux"), first_source)
        .expect("first Android stable-ID source should be writable");
    let first = fluxc::project::analyze(&root)
        .expect("first Android stable-ID app should analyze")
        .emit_c_for_target(fluxc::codegen::NativeTarget::Android)
        .expect("first Android stable-ID app should lower");

    let second_source = r#"fn pressed() -> void {
    print("pressed")
}
view Screen {
    grid columns: 1fr
    grid rows: auto auto auto
    Button inserted at 1,1
        text: "New"
    Button action at 2,1
        text: "Press"
        onPress: pressed
    Text title at 3,1
        text: "Title"
}
app Screen
"#;
    fs::write(root.join("src/main.flux"), second_source)
        .expect("second Android stable-ID source should be writable");
    let second = fluxc::project::analyze(&root)
        .expect("second Android stable-ID app should analyze")
        .emit_c_for_target(fluxc::codegen::NativeTarget::Android)
        .expect("second Android stable-ID app should lower");

    let title_id = android_stable_view_id("Screen", "title");
    let action_id = android_stable_view_id("Screen", "action");
    let inserted_id = android_stable_view_id("Screen", "inserted");
    for generated in [&first, &second] {
        assert!(generated.contains(&format!("set_stable_id, (jint){title_id}")));
        assert!(generated.contains(&format!("set_stable_id, (jint){action_id}")));
        assert!(generated.contains(&format!("case {action_id}: flux__fn_pressed(); break;")));
    }
    assert!(!first.contains(&format!("set_stable_id, (jint){inserted_id}")));
    assert!(second.contains(&format!("set_stable_id, (jint){inserted_id}")));

    let _ = fs::remove_dir_all(&root);
}

