#[test]
fn app_entry_rejects_unknown_parameterized_or_competing_main_roots() {
    let unknown = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Missing
"#;
    let errors = check_source_all(unknown).expect_err("unknown app root should fail");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("unknown app root view 'Missing'"))
    );

    let parameterized = r#"
view Screen(title: str) {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: title
}
app Screen
"#;
    let errors =
        check_source_all(parameterized).expect_err("bootstrap app root parameters should fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("app root view must not declare parameters")
    }));

    let competing = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen
fn main() -> i64 { 0 }
"#;
    let errors =
        check_source_all(competing).expect_err("app and main should not both define process entry");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("app declaration replaces fn main"))
    );
}

#[test]
fn typed_routes_bind_view_parameter_contracts_without_runtime_route_objects() {
    let source = r#"
view Home {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Home"
}
view Settings {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Settings"
}
route home = Home
route settings = Settings
app Home
"#;
    check_source(source).expect("typed route declarations should bind declared views");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
        .expect("typed routes should participate in semantic analysis");
    assert_eq!(database.program().routes.len(), 2);
    assert_eq!(database.program().routes[0].name, "home");
    assert_eq!(database.program().routes[0].view_name, "Home");
    assert!(
        database
            .symbols_named("home")
            .any(|symbol| { symbol.kind == fluxc::semantic::SymbolKind::Route })
    );
    let formatted =
        fluxc::formatter::format_source(source).expect("routes should format canonically");
    assert!(formatted.contains("route home = Home\n"));
    assert!(formatted.contains("route settings = Settings\n"));
    let generated =
        compile_to_c(source).expect("route declarations should not add a runtime object");
    assert!(!generated.contains("route home"));
    assert!(!generated.contains("route settings"));

    let unknown = r#"
view Home {
    grid columns: 1fr
    grid rows: auto
}
route missing = Missing
app Home
"#;
    let errors = check_source_all(unknown).expect_err("unknown route target must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("unknown route target view 'Missing'")
    }));

    let parameterized = r#"
view Detail(id: i64, *, tab: str = "overview") {
    grid columns: 1fr
    grid rows: auto
}
route detail = Detail
fn main() -> i64 { 0 }
"#;
    check_source(parameterized)
        .expect("route parameter contracts should be inferred from the target view");
    let parameterized_database =
        fluxc::semantic::SemanticDatabase::analyze(parameterized, SourceId::UNKNOWN)
            .expect("parameterized routes should participate in semantic analysis");
    let detail_route = parameterized_database
        .symbols_named("detail")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::Route)
        .expect("parameterized route symbol should exist");
    assert_eq!(
        detail_route.ty,
        Some(fluxc::ast::Type::Function {
            params: vec![fluxc::ast::Type::I64, fluxc::ast::Type::Str],
            returns: Vec::new(),
        })
    );
    let generated = compile_to_c(parameterized)
        .expect("parameterized route metadata should not add a runtime route object");
    assert!(!generated.contains("route detail"));

    let duplicate = r#"
view Home {
    grid columns: 1fr
    grid rows: auto
}
route home = Home
route home = Home
fn main() -> i64 { 0 }
"#;
    let errors = check_source_all(duplicate).expect_err("duplicate route identities must fail");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("duplicate route 'home'"))
    );

    let root = std::env::temp_dir().join(format!("flux-routes-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("route import fixture should be writable");
    fs::write(
        root.join("routes.flux"),
        "view Imported {\n    grid columns: 1fr\n    grid rows: auto\n}\nroute imported = Imported\n",
    )
    .expect("route dependency should be writable");
    let entry = root.join("main.flux");
    fs::write(
        &entry,
        "import \"routes.flux\"\nview Home {\n    grid columns: 1fr\n    grid rows: auto\n}\napp Home\n",
    )
    .expect("route entry should be writable");
    fluxc::project::check(&entry).expect("route declarations should merge across imports");
    let (program, _) = fluxc::project::load(&entry).expect("route project should load");
    assert!(program.routes.iter().any(|route| route.name == "imported"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn validates_flat_grid_bounds_and_rejects_accidental_overlap() {
    let valid = r#"
view Dashboard {
    grid columns: 1fr 1fr 1fr
    grid rows: 1fr 1fr
    Text title at 1,1 span columns 2
    Button action at 1,3 span rows 2
    Chart chart at 2,1 span columns 2
}
fn main() -> i64 { 0 }
"#;
    check_source(valid).expect("touching grid regions that do not overlap should typecheck");

    let out_of_bounds = r#"
view BadBounds {
    grid columns: 1fr 1fr
    grid rows: 1fr 1fr
    Text title at 2,2 span rows 2 span columns 2
}
fn main() -> i64 { 0 }
"#;
    let diagnostics =
        check_source_all(out_of_bounds).expect_err("spans beyond declared tracks must fail");
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("occupies grid row 3, but view 'BadBounds' declares only 2 rows")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("occupies grid column 3, but view 'BadBounds' declares only 2 columns")
    }));

    let overlap = r#"
view BadOverlap {
    grid columns: 1fr 1fr 1fr
    grid rows: 1fr 1fr
    Card summary at 1,1 span columns 2 span rows 2
    Text title at 2,2
}
fn main() -> i64 { 0 }
"#;
    let diagnostics = check_source_all(overlap)
        .expect_err("overlapping grid siblings must be explicit, not accidental");
    let overlap_error = diagnostics
        .iter()
        .find(|diagnostic| diagnostic.message.contains("overlaps sibling 'summary'"))
        .expect("overlap diagnostic should identify the earlier sibling");
    assert!(
        overlap_error
            .notes
            .iter()
            .any(|note| note.contains("grid overlay: true"))
    );
    assert_eq!(overlap_error.labels.len(), 1);

    let explicit_overlay = r#"
view Overlay {
    grid columns: 1fr 1fr
    grid rows: 1fr 1fr
    grid overlay: true
    Text backdrop at 1,1 span rows 2 span columns 2
        text: "Background"
    Button action at 2,2
        text: "Continue"
}
app Overlay
"#;
    check_source(explicit_overlay).expect("explicit overlay grids may intentionally overlap");
    let formatted = fluxc::formatter::format_source(explicit_overlay)
        .expect("explicit overlay syntax should format canonically");
    assert!(formatted.contains("    grid overlay: true\n"));

    let linux = compile_to_c(explicit_overlay)
        .expect("explicit overlay grid should lower through the native Linux grid");
    assert!(linux.contains("gtk_grid_attach(GTK_GRID(grid), flux__ui_backdrop, 0, 0, 2, 2)"));
    assert!(linux.contains("gtk_grid_attach(GTK_GRID(grid), flux__ui_action, 1, 1, 1, 1)"));

    let database = fluxc::semantic::SemanticDatabase::analyze(explicit_overlay, SourceId::UNKNOWN)
        .expect("explicit overlay fixture should analyze for Android lowering");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("explicit overlay grid should lower through the native Android grid");
    assert!(android.contains("grid_spec_weight, (jint)0, (jint)2, (jfloat)2.0f"));
    assert!(android.contains("grid_spec_weight, (jint)1, (jint)1, (jfloat)1.0f"));
}

#[test]
fn typechecks_bootstrap_view_element_property_contracts() {
    let valid = r#"
fn handle_press() -> void {
    print("pressed")
}

fn handle_drag(_offsetX: i64, _offsetY: i64) -> void {
}

fn handle_swipe(_velocityX: i64, _velocityY: i64) -> void {
}

fn handle_scale(_scalePercent: i64) -> void {
}

view App {
    grid columns: 1fr 1fr
    grid rows: auto 1fr
    Text heading at 1,1
        text: "Hello"
        selectable: true
    Button action at 1,2
        text: "Press"
        enabled: true
        onTap: handle_press
        onDoubleTap: handle_press
        onLongPress: handle_press
        onDrag: handle_drag
        onSwipe: handle_swipe
        onScale: handle_scale
        on_press: handle_press
    Chart chart at 2,1
        label: "Activity"
    Card summary at 2,2
        title: "Summary"
}

fn main() -> i64 { 0 }
"#;
    check_source(valid).expect("known view properties with matching types should typecheck");
    let database =
        fluxc::semantic::SemanticDatabase::analyze(valid, SourceId::from_name("typed-view.flux"))
            .expect("typed view properties should be available to editor semantics");
    let callback = database
        .symbols()
        .iter()
        .find(|symbol| symbol.name == "onTap")
        .expect("common tap callback property should be indexed");
    assert_eq!(
        callback.ty,
        Some(fluxc::ast::Type::Function {
            params: vec![],
            returns: vec![]
        })
    );
    let drag_callback = database
        .symbols()
        .iter()
        .find(|symbol| symbol.name == "onDrag")
        .expect("common drag callback property should be indexed");
    assert_eq!(
        drag_callback.ty,
        Some(fluxc::ast::Type::Function {
            params: vec![fluxc::ast::Type::I64, fluxc::ast::Type::I64],
            returns: vec![]
        })
    );
    let swipe_callback = database
        .symbols()
        .iter()
        .find(|symbol| symbol.name == "onSwipe")
        .expect("common swipe callback property should be indexed");
    assert_eq!(
        swipe_callback.ty,
        Some(fluxc::ast::Type::Function {
            params: vec![fluxc::ast::Type::I64, fluxc::ast::Type::I64],
            returns: vec![]
        })
    );
    let scale_callback = database
        .symbols()
        .iter()
        .find(|symbol| symbol.name == "onScale")
        .expect("common scale callback property should be indexed");
    assert_eq!(
        scale_callback.ty,
        Some(fluxc::ast::Type::Function {
            params: vec![fluxc::ast::Type::I64],
            returns: vec![]
        })
    );

    let invalid = r#"
view BadProperties {
    grid columns: 1fr 1fr
    grid rows: 1fr 1fr
    Text heading at 1,1
        text: false
    Button action at 1,2
        on_press: 42
    Text typo at 2,1
        texxt: "misspelled"
    Fancy custom at 2,2
}
fn main() -> i64 { 0 }
"#;
    let diagnostics =
        check_source_all(invalid).expect_err("invalid built-in view property contracts must fail");
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic.message.contains("property 'Text.text'")
            && diagnostic.message.contains("expected str, got bool")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic.message.contains("property 'Button.on_press'")
            && diagnostic
                .message
                .contains("expected fn() -> void, got i64")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("view element type 'Text' has no property 'texxt'")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("unknown view element type 'Fancy'")
    }));
}

#[test]
fn composes_parameterized_views_through_typed_data_properties() {
    let source = r#"
view Greeting(name: str, *, selectable: bool = false) {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: name
        selectable: selectable
}

view App {
    grid columns: 1fr
    grid rows: 1fr
    Greeting greeting at 1,1
        name: "Flux"
        selectable: true
}

fn main() -> i64 { 0 }
"#;
    check_source(source).expect("parameterized views should compose through typed properties");
    let program = fluxc::parser::parse(source).expect("parameterized view syntax should parse");
    assert_eq!(program.views[0].params.len(), 2);
    assert_eq!(program.views[0].params[0].name, "name");
    assert_eq!(program.views[0].params[1].default.as_ref().unwrap().line, 2);

    let formatted =
        fluxc::formatter::format_source(source).expect("parameterized views should format");
    assert!(formatted.contains("view Greeting(name: str, *, selectable: bool = false) {"));

    let database = fluxc::semantic::SemanticDatabase::analyze(
        source,
        SourceId::from_name("composed-view.flux"),
    )
    .expect("composed views should be indexed semantically");
    assert!(database.symbols().iter().any(|symbol| {
        symbol.name == "name"
            && symbol.kind == fluxc::semantic::SymbolKind::ViewProperty
            && symbol.ty == Some(fluxc::ast::Type::Str)
    }));
}

#[test]
fn rejects_invalid_or_cyclic_parameterized_view_composition() {
    let invalid = r#"
view Greeting(name: str, enabled: bool = true) {
    grid columns: 1fr
    grid rows: 1fr
    Text title at 1,1
        text: name
}

view App {
    grid columns: 1fr 1fr
    grid rows: 1fr
    Greeting missing at 1,1
        enabled: false
    Greeting wrong at 1,2
        name: 42
        extra: "nope"
}
fn main() -> i64 { 0 }
"#;
    let diagnostics =
        check_source_all(invalid).expect_err("invalid custom view properties should fail");
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("missing required parameter 'name' for 'Greeting'")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic.message.contains("property 'Greeting.name'")
            && diagnostic.message.contains("expected str, got i64")
    }));
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("view 'Greeting' has no parameter 'extra'")
    }));

    let cycle = r#"
view A {
    grid columns: 1fr
    grid rows: 1fr
    B b at 1,1
}
view B {
    grid columns: 1fr
    grid rows: 1fr
    A a at 1,1
}
fn main() -> i64 { 0 }
"#;
    let diagnostics = check_source_all(cycle).expect_err("recursive view composition must fail");
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic.message.contains("cyclic view composition")
            && diagnostic
                .notes
                .iter()
                .any(|note| note.contains("A -> B -> A") || note.contains("B -> A -> B"))
    }));
}

#[test]
fn view_composition_respects_module_visibility() {
    let root = std::env::temp_dir().join(format!("flux-view-visibility-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary view project should be writable");
    fs::write(
        root.join("components.flux"),
        r#"
view PrivateGreeting(name: str) {
    grid columns: 1fr
    grid rows: 1fr
    Text title at 1,1
        text: name
}

pub view PublicGreeting(name: str) {
    grid columns: 1fr
    grid rows: 1fr
    Text title at 1,1
        text: name
}
"#,
    )
    .expect("view component module should be writable");

    let good = root.join("good.flux");
    fs::write(
        &good,
        r#"
import "components.flux"
view App {
    grid columns: 1fr
    grid rows: 1fr
    PublicGreeting greeting at 1,1
        name: "Flux"
}
fn main() -> i64 { 0 }
"#,
    )
    .expect("public view entry should be writable");
    fluxc::project::check(&good).expect("public views should compose across modules");

    let bad = root.join("bad.flux");
    fs::write(
        &bad,
        r#"
import "components.flux"
view App {
    grid columns: 1fr
    grid rows: 1fr
    PrivateGreeting greeting at 1,1
        name: "Flux"
}
fn main() -> i64 { 0 }
"#,
    )
    .expect("private view entry should be writable");
    let diagnostics =
        fluxc::project::check(&bad).expect_err("private views must remain module-local");
    assert!(diagnostics.iter().any(|diagnostic| {
        diagnostic
            .message
            .contains("private view 'PrivateGreeting' is not accessible from this module")
    }));

    let _ = fs::remove_dir_all(&root);
}

