    fs::write(&c_path, generated).expect("generated null-aware list C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile null-aware list elements");
